window.BWY_REGIONS = ["日本", "中国", "韩国", "东南亚", "南亚 · 中东 · 非洲", "美洲", "欧洲", "大洋洲 · 海上"];
window.BWY = [{"v":0,"id":"mary","n":1,"t":"血腥玛丽","s":"午夜，浴室，一支蜡烛，对着镜子叫三遍她的名字。","o":"英美都市传说","r":[5,6],"a":"Bloody Mary","k":"血腥玛丽（Bloody Mary）是英语世界最出名的「镜子召唤」游戏。常见的玩法是：关灯的浴室里点一根蜡烛，对着镜子念三遍（也有念十三遍、边念边转圈的）她的名字，镜中便会出现一个满脸是血的女人——她也许会抓伤你，把你拖进镜子，或者只是尖叫。  它的前身是更古老的镜子占卜。十八、十九世纪的英美乡间流行在万圣节夜里举着蜡烛、倒退着走上楼梯，在镜中窥见未来丈夫的脸；若看见的是骷髅，就意味着出嫁前会死去。二十世纪初的万圣节明信片上常画着这一幕。  至于「玛丽」是谁，说法很多：有人说是迫害新教徒、一生求子不得的英格兰女王玛丽一世（于是有了对着镜子说「我偷了你的孩子」的玩法）；有人说是被处死的女巫；也有人说是车祸毁容的女孩。民俗学家珍妮特·兰格卢瓦在1970年代记录过美国孩子的一个版本，咒语是「玛丽·沃斯，我相信你」。如今它主要流传在孩子们的过夜派对上，是一场测试胆量的小小成人礼。  （本章中玛丽·沃"},{"v":0,"id":"kuchisake","n":2,"t":"裂口女","s":"梅雨季的黄昏，路灯下戴口罩的女人拦住放学的孩子：「我漂亮吗？」","o":"日本都市传说","r":[0],"a":"口裂け女","k":"裂口女（口裂け女）是日本战后流传最广的都市传说之一。她戴着大口罩、穿长风衣，在放学路上拦住孩子问：「我漂亮吗？」答「漂亮」，她就摘下口罩，露出一直裂到耳根的嘴，再问「这样也漂亮吗？」；答「不漂亮」，便会被她手里的剪刀（也有说是镰刀、菜刀）所伤。  嘴裂到耳根的女人，在江户时代的怪谈里就出现过：比如雨夜里被人招呼共撑一把伞的女子，一回头嘴裂到耳根，原来是狐狸所变；也有吉原游女回眸露出裂嘴的故事。不过不少研究者认为，1979 年的那一场是独立兴起的新传说。据说最早的「目击」发生在 1978 年末的岐阜县乡下——一位老妇人夜里在院子的茅厕边看见了她；一般认为 1979 年 1 月《岐阜日日新闻》的一篇专栏最早在报上提到这个「孩子们之间的传闻」。春天起周刊杂志接连报道，到了六月，传闻已经北到青森、南到鹿儿岛。许多学校组织集团下校、家长接送，一些地方警察加强了巡逻，还真有人扮成她的样子上街而被逮捕。"},{"v":0,"id":"hanako","n":3,"t":"厕所里的花子","s":"三楼女厕所，第三间。敲三下门，问：「花子同学，你在吗？」","o":"日本学校怪谈","r":[0],"a":"トイレの花子さん","k":"「厕所里的花子」（トイレの花子さん）是日本流传最广的学校怪谈。最常见的说法是：在学校三楼的女厕所，敲第三间隔间的门三下，问「花子同学，你在吗？」，门里就会传出一个小女孩的声音：「在——」。她被描述成留着娃娃头、穿白衬衫和红色背带裙的小学女生。有的版本里她只是应一声；有的版本里她会把人拖进马桶；也有人说，她只是想找人一起玩。  厕所怪谈本身由来已久。据说早在战后不久——1940年代末到1950年代——岩手县等地就流传着「从里数第三间厕所会传出『第三个花子』的声音，马桶里伸出一只白手」之类的故事。那时的「花子」大多只有声音，没有固定的模样。到了1980年代，她在孩子们之间口耳相传，楼层、敲门的次数、咒语和结局，各地都不一样：有的要从第一间一间一间敲到第三间，有的咒语是「花子同学，一起玩吧」（花子さん、遊びましょ）；还有学校说，男厕所里也住着一个和她作伴的「太郎」。  1990年，民俗学者常光彻"},{"v":0,"id":"hitori","n":4,"t":"一个人的捉迷藏","s":"凌晨三点，浴缸，一只塞满了米的布偶。这一次，当鬼的是它。","o":"日本网络怪谈","r":[0],"a":"ひとりかくれんぼ","k":"「一个人的捉迷藏」（ひとりかくれんぼ，Hitori Kakurenbo）是2000年代中期在日本网络上流传开的一种降灵游戏。据说它早先在关西、四国一带私下流传，与「狐狗狸さん」（こっくりさん，类似碟仙）并称；真正让它出名的是2ch（2ちゃんねる）的「オカルト超常現象板」——一般认为2006至2007年间有人贴出了详细做法，随后不断有人一边照做、一边用手机在帖子里「实况」，这种半直播的形式让它迅速扩散。也有一种说法认为，它是某个大学社团为研究都市传说如何传播而刻意放出来的。  流传最广的做法是：给有手有脚的布偶取名（不能用自己的名字），掏出棉花，塞进米和自己的指甲，用红线缝好，余线缠在身上；凌晨三点对它说三遍「第一个当鬼的是（自己）」，放进浴缸；关掉所有的灯、打开电视、闭眼数到十；拿着利器回浴室说「找到你了」并刺它，再说三遍「下一个当鬼的是（布偶）」，然后含着盐水躲起来。结束时含着盐水出来找"},{"v":0,"id":"elevator","n":5,"t":"电梯游戏","s":"4、2、6、2、10、5。五楼进来的那个女人，不要看她。","o":"韩国 · 日本网络怪谈","r":[0,2],"a":"Elevator Game","k":"「电梯游戏」（Elevator Game，也叫「去异世界的电梯」）是网络时代最出名的仪式型怪谈之一。玩法大同小异：找一栋至少十层的楼，独自进电梯，依次按 4、2、6、2、10，途中有人进来就算失败；到十楼后按 5，五楼可能会进来一个年轻女人，不能看她、不能和她说话；接着按 1，如果电梯不下反上、一路升到十楼，就说明你到了「另一个世界」——那里只有你一个人，灯是黑的，据说窗外远处能看见一个红色的十字。  它的出处一直说不清。一种说法是起源于韩国，2010 年前后在韩国网络上流传，还被画成过漫画；另一种说法认为更早出现在日本的匿名论坛上。2010 年代初，英文论坛和怪谈网站上开始出现各种转述和翻译，每传一次细节就变一点：电子设备能不能用、回来时要不要在中途按别的楼层、五楼的女人到底是什么，各个版本说法都不一样。  回来的方法同样众说纷纭：多数版本要求原路再按一遍顺序，回到一楼后仔细确认周围是不"},{"v":0,"id":"bus375","n":6,"t":"375路末班车","s":"深夜，从圆明园开往香山的末班车，在没有站的地方停了下来。","o":"中国大陆网络都市传说","r":[1],"a":"","k":"「375路末班车」是中国大陆流传最广的网络都市传说之一（也有330路、331路等说法）。最常见的版本是这样的：1995年11月14日深夜，一辆从圆明园开往香山的末班公交车上，只有司机、女售票员、一位老太太和一个小伙子。车在没有站的地方停下，上来三个穿清朝衣服、脸色惨白的人——两个人架着中间一个低着头的。售票员以为是附近拍古装戏的演员。不久，老太太忽然一口咬定小伙子偷了她的钱包，硬把他拽下了车。下车后她才说：那三个人没有脚，风一吹，袍子底下是空的。第二天，这辆末班车连同司机、售票员一起失踪；据说后来在很远的一座水库里找到了车，车里有三具已经腐烂的尸体，油箱里装的不是油，而是血。  据说这个故事从1990年代末到2000年代，在BBS、论坛和口耳相传中扩散开来，又经博客、贴吧、视频一遍遍转述，细节越传越具体：精确的日期、线路号、站名、「油箱里的血」、圆明园与清朝装束的联系……有的版本说车是在密"},{"v":0,"id":"hitchhiker","n":7,"t":"消失的搭车客","s":"雨夜的老公路上，穿白色舞裙的姑娘招手搭车。她说，她只想回家。","o":"美国都市传说","r":[5],"a":"The Vanishing Hitchhiker","k":"「消失的搭车客」（The Vanishing Hitchhiker）大概是美国流传最广的都市传说。骨架几乎从不改变：夜里开车的人在路边载上一个年轻姑娘——常常穿着白裙子，或者刚从舞会回来——她报出一个地址，一路上很少说话；车开到半路，人却不见了。司机按地址找过去，开门的老人告诉他：那是我的女儿，很多年前的今天死在这条路上。你不是第一个了。  1942到1943年，民俗学家理查德·比尔兹利和罗莎莉·汉基在《加利福尼亚民俗季刊》上发表了对这个故事的系统研究，他们从全美各地收集了七十多个书面版本，归纳出几种主要类型——其中一类里，搭车客在消失前会留下一句预言（比如战争何时结束、某场灾难）。据说更早的版本里，载人的是马车或骑马的旅人；欧洲民间也有许多「途中消失的乘客」的故事。1981年，扬·哈罗德·布鲁范德用它做了自己那本都市传说研究的书名，这本书也让「都市传说」这个说法走进了大众视野。  故事在"},{"v":0,"id":"monkeypaw","n":8,"t":"猴爪","s":"三个人，每人三个愿望。苦行僧要让世人知道：命运不容插手。","o":"英国短篇小说 · 1902","r":[6],"a":"The Monkey's Paw","k":"《猴爪》（The Monkey's Paw）是英国作家W·W·雅各布斯（1863–1943）的短篇小说，1902年9月首刊于美国的《哈珀月刊》，同年收入他的短篇集《驳船上的女人》。雅各布斯平生以写码头、水手和驳船船夫的幽默故事闻名，偏偏是这篇阴冷的小说，成了他流传最广的作品。  故事很短：一个印度苦行僧在猴爪上施了咒，要让世人明白命运不容插手——三个人可以凭它各许三个愿望，每一个愿望都会实现，却以最残酷的方式。怀特一家许下的两百英镑，变成了儿子的抚恤金；第二个愿望让死者归来；第三个愿望把它送了回去。有读者注意到，怀特先生正好是猴爪的第三个持有者——第一个人、莫里斯、怀特，咒语到他这里就用完了（这是一种解读，原著没有明说）。原著从头到尾没有让门外的东西露面，读者只听见敲门声——这种「不写」，后来常被当作恐怖小说留白的范本。  小说发表的第二年（1903年）就被改编成独幕剧，在伦敦干草市场剧院"},{"v":0,"id":"huapi","n":9,"t":"画皮","s":"书斋里藏着一个美人。夜里，她把自己的脸铺在床上，一笔一笔地画。","o":"清·蒲松龄《聊斋志异》","r":[1],"a":"","k":"《画皮》出自清代蒲松龄（1640–1715）的文言短篇小说集《聊斋志异》，是全书流传最广的篇目之一。故事很短：太原王生清早在路上遇见一个自称逃妾的美貌女子，把她藏进书斋；集市上的道士说他身上有邪气，他不信，心里还当道士是想借驱邪骗钱。回家后他从窗外偷看，才看见一个面色青翠、牙齿如锯的厉鬼，把人皮铺在床上用彩笔描画，画完披在身上，又成了美人。道士给的拂尘没能挡住它，厉鬼撞开房门，裂开王生的胸腹，掏走了心。  后半篇的主角是王生的妻子陈氏。道士追到王生弟弟二郎的南院，仗剑立在庭中，喝一声「孽魅！偿我拂子来！」，打得画皮脱落，斩下鬼头，用葫芦收了化成的浓烟，又把人皮像画轴一样卷走；却自称道行太浅，不能起死回生，只指点陈氏去求集市上一个躺在粪土里的疯乞丐。陈氏当众被他打骂、取笑，最后咽下他递到嘴边的痰；回家哭尸时呕出一颗还在跳动的人心，落进丈夫的胸腔，用帛缠紧，王生竟活了过来。疯子究竟是谁，原文没"},{"v":0,"id":"llorona","n":10,"t":"哭泣的女人","s":"亡灵节之夜，河边有个女人一直在哭：「哎呀，我的孩子们！」","o":"墨西哥民间传说","r":[5],"a":"La Llorona","k":"「哭泣的女人」（La Llorona）是墨西哥流传最广的鬼魂传说。最常见的版本是：美丽的玛丽亚嫁给了有钱的男人，丈夫变了心、离她而去，她在绝望和愤怒中把两个孩子淹死在河里，清醒过来后自己也投了河。她死后被挡在另一个世界的门外，除非找回自己的孩子；于是她穿着白衣、蒙着面纱，永远在河边和水边游荡，哭喊着「¡Ay, mis hijos!」（哎呀，我的孩子们！），把夜里在水边逗留的孩子当成自己的孩子带走。  它的源头众说纷纭。一般认为这个故事成形于殖民时期的墨西哥；也有人把它追溯得更早——十六世纪方济各会修士萨阿贡主持编写的《佛罗伦萨手抄本》，记载了西班牙人到来之前的八个凶兆，其中第六个，就是夜里有个女人哭喊着为她的孩子们哀叹。有学者把她和阿兹特克的母神西瓦科亚特尔（Cihuacóatl）联系起来；另一种流行的说法，则把她和科尔特斯的翻译兼情人玛琳切（La Malinche）混为一谈，让她成了为混"},{"v":0,"id":"kisaragi","n":11,"t":"如月车站","s":"末班车二十多分钟没有停站。车门打开时，站名牌上写着：きさらぎ。","o":"日本 2ch 网络怪谈","r":[0],"a":"きさらぎ駅","k":"「如月车站」（きさらぎ駅）是日本网络怪谈的代表作。2004年1月8日深夜十一点多，日本匿名论坛 2ch 的オカルト（超自然）板上，在一个「身边发生怪事就来实况」的帖子里，一位女性发帖人开始求助：她说自己坐上了静冈县某私铁的电车，平时几分钟一站的线路，这趟车却二十多分钟没有停站，车上的乘客全都睡着了。车终于停在一个叫「きさらぎ」的无人车站；据说站名牌上相邻的两站，分别写着「かたす」和「やみ」。  帖子里的网友一边帮她查地图，一边出主意。她打电话给家里，家人不知道这是哪儿，没法来接；她也报了警，警察查不到这个站，没把她的话当真。她沿着铁轨往回走，听见远处传来太鼓和铃铛的声音；身后有人喊「别走在铁轨上」，回头一看是个只有一条腿的老人，转眼就不见了。她穿过一条叫「伊佐貫」的隧道，在隧道那头遇到一个说要开车送她去车站的男人。网友劝她小心，她还是上了车。她说车一直往山里开，司机不说话，嘴里开始念叨听不"},{"v":0,"id":"hasshaku","n":12,"t":"八尺大人","s":"盛夏的乡下，树篱上方，一顶白色的宽檐帽慢慢走过。ぽ、ぽぽ、ぽ。","o":"日本网络怪谈","r":[0],"a":"八尺様","k":"「八尺大人」（八尺様，Hasshaku-sama）出自日本网络论坛2ch的オカルト板。一般认为它最早发表于2008年8月，贴在「死ぬ程洒落にならない怖い話を集めてみない？」（收集真正吓人到笑不出来的故事）系列帖里：发帖人回忆上高中时，骑摩托去乡下的爷爷奶奶家玩，在院子里看见树篱上方有一顶白帽子移过去——树篱有两米多高，帽子底下是一个穿白连衣裙的女人，同时听到「ぽぽぽ」的奇怪声音。爷爷奶奶听了脸色大变，请来一位老婆婆，让他独自在一间窗户糊满报纸、贴着护符、四角放着盐、木箱上供着佛像的房间里过夜。夜里门外传来爷爷的声音叫他开门，他没有应；第二天早上，盐变成了黑色。之后，同一血脉的亲戚们围坐在一辆面包车里，把他夹在中间护送出村，路上那个声音一直跟着车，他被告诫绝对不能抬头睁眼。也有转述提到，他在车上没忍住，偷偷往窗外瞥了一眼，只看见白色的衣服跟着车一起走。  据帖中的说法，「八尺」（约两米四）是"},{"v":0,"id":"saruyume","n":13,"t":"猿梦","s":"昏暗的小站，猴子模样的小火车。广播报出下一个人的死法——快醒过来。","o":"日本网络怪谈","r":[0],"a":"さるゆめ","k":"「猿梦」（さるゆめ）是日本网络时代最有名的怪谈之一。据说它最早是1999年前后投稿到个人怪谈网站上的一篇《恐怖的广播》（恐怖のアナウンス），2000年夏天被转贴到大型匿名论坛「2ちゃんねる」超常现象板的怪谈串里，之后才以「猿梦」这个标题流传开来。讲述者以第一人称说自己做过的一个梦：在一个昏暗的无人小站里，广播说「电车马上就要来了，坐上去的话，你会遇到可怕的事哦」；驶来的是游乐园里那种猴子小火车，乘客们面无表情地坐着，他坐在从后面数第三个位子。  车开动后，广播一个一个地报：「下一个是活造り」——最后面的男人被几个披着破布的小人像片活鱼一样剖开；「下一个是挖眼」——他正后方的长发女人被小人用勺子一样的东西挖出眼睛；「下一个是绞肉」——轮到他自己，小人带着机器爬上他的膝盖。他闭上眼睛拼命想「这是梦，快醒过来」，在越来越近的机器声和吹到脸上的风里醒了过来。原帖说，几年以后他又做了同一个梦，「接着"},{"v":0,"id":"ganshi","n":14,"t":"湘西赶尸","s":"夜半的山路上响起阴锣。客店的大门终年不关，门后靠墙，站着戴斗笠的「喜神」。","o":"中国湘西民间传说","r":[1],"a":"","k":"「湘西赶尸」是流传在湖南西部沅水流域（沅陵、辰溪、泸溪、溆浦一带）的民间传说。据说客死他乡的人，可以由「赶尸匠」作法，让尸体自己一跳一跳地走回家乡入土。赶尸匠把尸体叫作「喜神」，夜行昼宿：天黑才上路，前头有人敲「阴锣」、摇铃，通知沿途的人回避、拴狗；鸡叫之前必须赶到专门接待他们的客店歇脚。传说这种客店的大门终年不关，喜神白天就靠墙站在门板后头。尸体额头贴着朱砂画的「辰州符」，头戴斗笠或罩着黑布。  关于什么人能赶，流传最广的是「三赶三不赶」：据说砍头的、受绞刑的、站笼站死的可以赶——死于非命，魂魄被法术拘在身上；病死的、投河上吊的、雷打火烧的不赶。起源也有几种说法：一种上溯到蚩尤，说他率兵作战，为把阵亡的将士带回故乡，命军师作法驱尸；更多的说法把它和「辰州符」「祝由」这类湘西巫术连在一起。辰州（今沅陵）一带出产朱砂，所以朱砂又叫「辰砂」。据说沈从文写湘西的散文里，也提到过辰州符与赶尸这类传"},{"v":0,"id":"chaonei81","n":15,"t":"朝内81号","s":"北京朝阳门内，两栋没人住的洋楼。夜班车每晚都在门口停一下，没有人下车。","o":"北京网络都市传说","r":[1],"a":"","k":"朝内81号是北京东城区朝阳门内大街上的一座院子，院里东西两栋灰砖洋楼，地上三层，带地下室和阁楼，屋顶是法式的「蒙萨」双折顶。一般的说法是始建于1910年前后，但最初是谁盖的、做什么用，说法一直不一：有报道说是美国天主教本笃会出资修建，也有人说是京汉铁路一位法国经理的住宅。据说二三十年代这里办过教外国传教士、外交官学中文的学校；1946年，比利时天主教奥斯定修女会在楼里开过一间「普德诊所」，一直开到北平解放。此后楼房先后归一些机关单位使用；据说文革时红卫兵短暂占用过，之后就长期空置、年久失修。1994年前后产权交给了天主教团体，2009年前后被列为文物保护单位。  大约从2000年代中期开始，有人翻墙进去探险拍照，「朝内81号」的鬼宅之名在论坛上越传越广，被排进「北京四大鬼宅」。流传最广的版本是：1949年，一位国民党军官逃往台湾，丢下的太太（也有说是姨太太、情人）在东楼里上吊自尽，此后打雷"},{"v":0,"id":"redgirl","n":16,"t":"红衣小女孩","s":"一卷家庭登山录像带。队伍最后面，跟着一个谁也不认识的红衣小女孩。","o":"台湾都市传说","r":[1],"a":"","k":"「红衣小女孩」是台湾流传最广的都市传说之一。一般的说法是：1998年前后，一个家庭到台中大坑一带的登山步道健行，用当时俗称「V8」的8厘米家用摄影机录下了出游过程。据说这段录像后来寄给了电视台，在 TVBS 的灵异节目《神出鬼没》里播出——画面中，队伍的最后面跟着一个穿红色衣服的小女孩（有的版本说她还戴着红帽子），全家人都说不认识她，拍摄的时候也没有人注意到她。节目把画面一格一格放大，说她的脸不像小孩，倒像一个表情古怪的老人。  录像播出以后，传言越滚越大：有人说看过录像的人会倒楣；也有一种流传很广的说法，说片中走在她前面的那位家人不久后就过世了。这些说法都没有可靠的证据，也查不到当事人出面证实。不少人认为，她不过是同一条步道上别家登山客的孩子，因为录像画质粗糙、角度凑巧，才被看成了「鬼」。  更多人把她和台湾民间的「魔神仔」连在一起。魔神仔是山林里的精怪，传说身形矮小、像个孩子，有时也会"},{"v":0,"id":"bixian","n":17,"t":"笔仙","s":"两只手背交叉，握住一支红笔。「笔仙笔仙，我是你的今生，你是我的前世……」","o":"中国校园怪谈","r":[1],"a":"","k":"「笔仙」是中国大陆校园里流传最广的招灵游戏之一，八九十年代起在中学生中盛行。玩法是：两个人手背交叉（也有手指相扣、手心相对的说法），一起握住一支笔，笔尖立在写着「是」「否」和数字的白纸上，念一段召请的话——最常见的版本是「笔仙笔仙，我是你的今生，你是我的前世，若要与我续缘，请在纸上画圈」，也有把「前世」「今生」前后颠倒的念法。笔若自己画了圈，就说明「笔仙」来了，可以向它提问。  与它相伴的是一串禁忌：中途不能松手，否则笔仙回不去，会「留下来」；不能问它是怎么死的；不能问自己什么时候死；问完一定要送走，送走时要等它画圈；用过的纸要烧掉，笔要折断或扔掉。有的版本还要求开一扇窗给它进出，有的说不能在阴雨天或夜里玩；也有说法认为笔仙是附近徘徊的亡魂，问到它的死因会让它「重演一遍」。这些规矩各校各不相同，大多靠学长学姐口耳相传，再添油加醋；「没烧的纸、没扔的笔会自己回来」是其中流传很广的一种吓人说法"},{"v":0,"id":"bellwitch","n":18,"t":"贝尔女巫","s":"它敲墙，扯被子，唱赞美诗。它说它要缠着老贝尔，一直缠到他进坟。","o":"美国田纳西州民间传说 · 1817—1821","r":[5],"a":"","k":""},{"v":0,"id":"maenak","n":19,"t":"鬼妻娜娜","s":"运河边的高脚屋里，妻子抱着孩子，等丈夫从战场回来。","o":"泰国民间传说","r":[3],"a":"Mae Nak Phra Khanong","k":"「帕卡农的娜娘」（Mae Nak Phra Khanong）是泰国家喻户晓的鬼故事。据说它发生在十九世纪中叶、拉玛四世在位的时候，地点是曼谷城外帕卡农运河边的一个村子。年轻的妻子娜怀着身孕，丈夫麦被征去打仗；娜在分娩时连同腹中的孩子一起死去。麦回来以后，妻子抱着孩子在家里等他，一切如常。邻居们想提醒他，有的不敢开口，有的开了口就遭了殃。直到有一天，娜在屋里舂辣椒酱，一个青柠从地板缝里掉到了高脚屋底下——她把手臂伸得老长，一直伸到地上把它捡了回去。麦这才明白，借口下楼解手，一路逃进了玛哈布寺。逃的这一段各家说法不同：有的说他躲在寺里僧人用圣线围起来的地方，有的说他钻进了一丛鬼魂害怕的艾纳香（泰语叫 naat），娜找不到他，只好在外面哭。  泰国旧俗把「死的时候孩子还在肚子里」的女人叫作「tai thong klom」（ตายทั้งกลม，大意是母子囫囵着一起走），认为她们化成的鬼最凶，也最"},{"v":0,"id":"blackeyed","n":20,"t":"黑眼孩子","s":"深夜，有人很有礼貌地敲你的车窗：「女士，能让我们进去吗？」","o":"美国网络都市传说","r":[5],"a":"Black-Eyed Kids","k":"「黑眼孩子」（Black-Eyed Kids，常简称 BEK）是网络时代土生土长的美国都市传说。一般认为它源自1998年：得克萨斯州阿比林的一位本地记者，在一个讨论灵异话题的邮件列表上写下了自己的「亲身经历」——深夜，他坐在电影院停车场的车里，借着顶灯给网费写支票，两个十来岁的男孩来敲车窗，说想看电影却把钱落在家里，请他载一程。孩子们措辞礼貌得过分，一再催促：「我们没带枪」「你不说可以，我们就上不了车」。他说自己的手不知不觉已经伸向了门锁；就在这时，他看清了他们的眼睛——没有眼白，整个眼眶都是黑的。他发动汽车逃走了。多年以后，他还在报纸专栏里重讲过这段经历，坚持说那是真事。  帖子被不断转载，此后陆续有大量网友讲述类似的「亲历」：孩子总是成对出现，十岁到十六岁上下，穿着普通甚至过时的衣服，脸色苍白，说起话来平板、老成，像个大人；他们敲的不只是车窗，更多是深夜住宅的门，也出现在汽车旅馆和公寓"},{"v":0,"id":"kunekune","n":21,"t":"くねくね","s":"盛夏正午，田的那一头有个白色的东西在扭。远远看着不要紧——千万别想看清楚它是什么。","o":"日本网络怪谈（2ch）","r":[0],"a":"くねくね","k":"「くねくね」是日本的网络怪谈，名字是个拟态词，意思就是「扭来扭去」。据说最早的雏形在2000年前后就出现在网上：有人转述朋友小时候的经历——在乡下从窗口望见田里有个白色的东西，关节古怪地扭动；一起看的哥哥看着看着，好像「明白」了什么，从此就疯了。2003年前后，日本匿名论坛2ch灵异版（オカルト板）上流传开的一篇把故事定了型：一个孩子和哥哥回乡下外婆家，看见远处水田里有一个白色的人形东西，一刻不停地扭；哥哥拿来望远镜去看，看清之后脸色大变，只说了一句「わからないほうがいい」（不知道比较好），从此痴痴呆呆，像变了一个人。外婆哭着说那东西是不能看的；家里人最后决定，哥哥不能带回城里了，就留在乡下养着——「过几年，放回田里去」。  在一遍遍的转贴和「我也见过」的回帖里，它的规矩渐渐固定下来：多在晴朗炎热的白天出现，常在水田、河边，也有人说在海边、在楼顶；远远看着不要紧，一旦「理解」了它是什么，人"},{"v":0,"id":"teketeke","n":22,"t":"テケテケ","s":"冬夜的校舍里，有人用两只手肘撑着地，テケ、テケ、テケ地爬过来。","o":"日本校园怪谈","r":[0],"a":"テケテケ","k":"「テケテケ」是日本流传很广的校园怪谈。传说她是一个只有上半身的女孩，用两只手肘（也有说是双手）撑着地面飞快地爬，发出「テケ、テケ」的声音，因此得名。据说她快得像汽车（有的说时速上百公里），追上人之后会把对方也拦腰截断；有的版本里，她手里还拿着一把镰刀。她出没的地方，多是黄昏或夜里的学校走廊、厕所，还有铁路道口。  流传最广的起源故事发生在北海道（有一种说法是室兰）：冬天，一个女孩掉在铁轨上，被列车截成了两半。据说因为天太冷，伤口很快冻住了，她没有立刻死去，而是在铁轨上爬了一段。讲故事的人往往会加一句「这是真事」，但并没有能对上的报道或记录。  她和更早的「カシマさん」（カシマ·レイコ）传说几乎缠在一起。那一类故事里，没有脚的女人会问「我的脚在哪里？」「你要脚吗？」，或者问你她叫什么。各地的「正确答案」都不一样：脚在「名神高速公路上」；名字要答「カシマさん」，有的地方还要拆字——「仮面的カ、"},{"v":0,"id":"akaheya","n":23,"t":"赤い部屋","s":"弹出来的窗口只有一句话。关掉它，它会再弹出来——比上一次长一点。","o":"日本网络都市传说","r":[0],"a":"赤い部屋","k":"「赤い部屋」（红色房间）是日本最早的网络怪谈之一。据说它在 1990 年代末先以文字的形式在网上流传，世纪之交前后又出现了被大量转载的 Flash 动画版本（具体年份说法不一）：一个少年上网时，屏幕上弹出一个窗口，只有一句话——「あなたは赤い部屋が好きですか？」（你喜欢红色的房间吗？）。他关掉它，它又弹出来，句子一次比一次长；有的版本说，这句话还会被一个小孩子的声音念出来。最后整个屏幕变成红色，上面列着一串人名，其中有他朋友的名字。第二天，少年死在自己的房间里，墙壁被涂成了红色。  它诞生在拨号上网的年代。深夜的「テレホーダイ」（电话费包月）时段挤满了聊天室和个人主页，而「ブラクラ」（浏览器崩溃程序）——用脚本不停打开新窗口、直到电脑死机的恶作剧网页——让很多人真的被「关不掉的窗口」吓到过。有一种说法认为，赤い部屋的恐怖正是从这种真实的体验里长出来的：你以为自己掌控着屏幕，其实并没有。  "},{"v":0,"id":"huangpizi","n":24,"t":"黄皮子讨封","s":"雪夜的道上，一只戴草帽的黄鼠狼人立起来，问你：「你看我像人，还是像神？」","o":"中国东北民间传说","r":[1],"a":"","k":"「黄皮子讨封」（也叫「讨口封」）流传于东北、华北的农村。黄皮子就是黄鼬，俗称黄鼠狼。民间相信它修炼到一定年头，会在夜里或荒路上戴着草帽、披着衣裳，像人一样直立起来拦住行人，作揖发问：「你看我像人，还是像神？」据说它要借人的一句话来「封正」：答「像神」，它就得了正果，日后会报答那个人；答「像人」，或者说破它是个黄鼠狼，它多年的道行就一下子散了，从此记恨，找上门来报复。也有说法正好相反，认为替它「封神」的人反倒要折福，所以有经验的老人遇上了宁可不答，绕着走，或者绕着弯子说话。讨封的也不只是黄皮子：据说狐狸也会，蛇讨封问的则是「你看我像不像龙」。版本很多，各地并不一致。  这个传说长在更大的民间信仰里。东北民间有「五大仙」或「五大家」的说法，常见的写法是「狐黄白柳灰」（「狐」常写作「胡」）——狐狸、黄鼬、刺猬、蛇、老鼠；北京、天津一带的旧说法则叫「四大门」，只算前四家。人们相信这些动物修行有成，"},{"v":0,"id":"bunnyman","n":25,"t":"兔子人","s":"万圣节午夜，铁路桥洞，一个穿白色兔子装、拿着斧头的男人。","o":"美国弗吉尼亚州都市传说","r":[5],"a":"Bunny Man","k":"「兔子人」（Bunny Man）是美国弗吉尼亚州费尔法克斯县最出名的都市传说。真正登过报纸的，只有1970年10月的两件事：一对年轻人深夜把车停在路边，一个穿白衣服、戴长兔耳头套的男人从黑暗里走出来，嚷着他们擅闯私人土地，把一把短柄斧头砸进了车窗；十来天后，一名工地保安看见一个穿兔子装的人站在一栋没完工的新房子门廊下，用斧头一下一下地砍柱子，嘴里同样嚷着「擅闯」。两次都没有人受伤，警方调查了一阵，始终没有找到这个人。据说之后几个星期里又冒出了不少目击报告，但没有一份得到证实。  后来的故事越讲越大，也越讲越老：据说二十世纪初，克利夫顿附近的一所精神病院关门，押送病人的车在科尔切斯特路上翻了，两个病人逃进树林；附近开始出现剥了皮、挂在树上的兔子；其中一个被发现吊死在铁路桥洞下，另一个就成了「兔子人」。有的版本说，他每年万圣节午夜回到桥洞，专找还待在洞里的人，第二天人就挂在桥上；有的版本给两个"},{"v":0,"id":"smilingman","n":26,"t":"微笑的男人","s":"凌晨的空街上，一个瘦高的男人跳着舞朝你走来。他在笑。他一直没看你。","o":"英文网络怪谈","r":[5],"a":"The Smiling Man","k":"「微笑的男人」（The Smiling Man）是 2012 年发在 Reddit 上的一篇「亲历」故事。一般认为最早贴在专门讲「遇到可怕陌生人」的版块，后来又在恐怖故事版块被大量转载。讲述者说自己当年住在美国一座大城市的市中心，睡不着就在深夜出门散步。一个凌晨一两点，他在一条空荡荡的小街上，看见一个又高又瘦、穿着旧西装的男人朝他过来：步子像在跳华尔兹，转一圈，再往前大大地迈一步；头往后仰，看着天，眼睛瞪得很大，脸上挂着一个大得像动画片里的笑容。  讲述者躲到马路对面，那人停下，一只脚踩在马路上，仍然仰头笑着。讲述者往前看了一眼再回头，他已经不见了——下一刻却出现在讲述者这一侧，蹲着，接着用一种夸张的、动画片里偷偷摸过来似的踮脚步子飞快逼近，停在大约一辆车远的地方，始终看着天。讲述者想喝问他，喊出来的却只是一声呜咽。那人转身跳着舞走开，又突然掉头冲了回来。讲述者一路跑到有车的大路上，再没见"},{"v":0,"id":"balete","n":27,"t":"巴雷特大道的白衣女人","s":"凌晨的老路，两旁是住着精灵的榕树。别看后视镜——她就坐在后座上，在找什么东西。","o":"菲律宾马尼拉都市传说","r":[3],"a":"Balete Drive","k":"巴雷特大道（Balete Drive）是马尼拉大都会奎松市新马尼拉区的一条老路。据说它得名于从前长在路中央的一棵巨大的 balete 树，车到那里都得绕着走；那棵树如今已经不在了。balete 是一类会缠绕、绞杀宿主的榕属植物，菲律宾民间普遍相信它是精灵和鬼魂的住处：树杈上坐着抽大雪茄的巨人 kapre，还有 diwata、tikbalang；树旁的土丘里住着「土丘老人」nuno sa punso。很多人家不愿在院子里种它。经过大树或荒僻的地方，老一辈会低声说一句「Tabi tabi po」——请让让路，免得冒犯看不见的住户。  白衣女人（White Lady）的故事据说从二十世纪五十年代就开始流传。最常见的讲法是：深夜开车经过的人，看见一个白衣长发的年轻女人在路边招手；或者一抬眼，她已经坐在后座上了，再回头，座位是空的。有的说她很美，有的说她脸上带着伤和血。据说五十年代有一位警官讲过：他"},{"v":0,"id":"enfield","n":28,"t":"恩菲尔德闹鬼案","s":"伦敦北郊的一栋公屋。墙里在敲，椅子在走，十一岁的女孩用一个老人的嗓音说话。","o":"英国伦敦 · 1977年","r":[6],"a":"Enfield Poltergeist","k":"恩菲尔德闹鬼案（Enfield Poltergeist）发生在1977年8月到1979年间，地点是伦敦北郊恩菲尔德的一栋公屋，住着一位离异的母亲和她的四个孩子。一开始是床在摇、墙里有拖着脚走路和敲击的声音；据说第一晚赶来的女警在证词里写道，她亲眼看见一把椅子在地板上自己滑了一段距离。之后是积木和弹珠在屋里飞、抽屉柜自己挪动、二女儿被「从床上抛起来」；据说还有路过的人说，隔着楼上的窗户看见书本和那个女孩悬在半空。一家小报派来了记者和摄影师，摄影师用遥控连拍拍下的「悬浮」照片，后来成了这个案子最出名的图像。  英国心灵研究会的两位调查员前后在这户人家待了一年多，录下了一百多个小时的磁带。最让人发毛的是那个声音：一个十一岁的女孩喉咙里，发出一个粗哑的老人的嗓音，自称是这屋子从前的住户，说自己临死前眼睛瞎了，在楼下角落的椅子上睡着，就这么死了。据说后来确实查到，曾有一位老人在这屋子里去世。相信者认"},{"v":0,"id":"bridepool","n":29,"t":"新娘潭","s":"黄昏的山涧，夜里有人吹唢呐。听见了，不要回头，不要应声。","o":"香港新界都市传说","r":[1],"a":"","k":"新娘潭位于香港新界东北的船湾郊野公园，是一条有好几级瀑布和深潭的山溪，也是烧烤和行山的热门地点。流传最广的说法是：清朝时（也有人说是民国初年），一顶花轿从乌蛟腾抬往鹿颈，四名轿夫路过潭边时正逢雨后，山石湿滑，一人失足，花轿翻侧，新娘跌进瀑布下的深潭溺死，水潭从此被叫作「新娘潭」。据说村民后来在溪上修了一道石桥，就是今天的新娘桥，有说法称桥建于1906年（光绪三十二年）。另一个版本则说，在这里阴阳相隔的是一对新婚夫妇。  附近还有一个「照镜潭」，潭水平静如镜。一种说法是新娘出嫁前在这里梳妆照镜；另一种说法更阴森：有人看见潭边站着一个女人，水里却没有她的倒影。  几十年来，传闻越积越多：夜里听见吹箫打鼓的迎亲声，四周却不见人；有人在水里看见一双穿红鞋的脚；骑电单车经过新娘潭路，车尾多了一个人……它常被列为香港的「四大鬼域」之一，也有人说这里的意外是冤魂在「找替身」。这些都属于都市传说。真实的情"},{"v":0,"id":"kuntilanak","n":30,"t":"坤蒂拉娜","s":"停电的雨夜，鸡蛋花香。笑声听着越远，她就离你越近。","o":"印度尼西亚 / 马来民间传说","r":[3],"a":"Kuntilanak","k":"坤蒂拉娜（Kuntilanak），马来半岛和新加坡一带多叫庞蒂雅娜（Pontianak），是印度尼西亚、马来西亚等地流传最广的女鬼。通常的说法是：她生前是一个死于难产、或怀着孩子死去的女人，死后穿着白衣、披着一头长发，夜里栖在大树上——榕树、木棉、鸡蛋花树。她出现之前，人们会先闻到一阵鸡蛋花（frangipani，印尼人叫 kemboja，常种在坟场里）的香味，香味随后变成腐臭；她会发出婴儿似的哭声，或者尖细的笑声。最著名的一条规矩是：笑声听起来很远，她其实就在身边；听起来很近，她反而还远。  关于名字，有一种民间说法把 pontianak 解释成「死于分娩的女人」（perempuan mati beranak）的缩略，学界并不都认同；二十世纪初英国殖民官员记录的马来民俗里，pontianak 有时指的是死产的婴儿，而难产而死的母亲另有名字，叫「兰苏尔」（langsuir）。各地版本差异很"},{"v":1,"id":"merry","n":1,"t":"玛丽的电话","s":"搬家那天，你扔掉了旧洋娃娃玛丽。夜里电话响了：「我是玛丽，我现在在垃圾站。」","o":"日本都市传说","r":[0],"a":"メリーさんの電話","k":"「メリーさんの電話」（玛丽的电话）是日本流传很广的都市传说。最常见的版本是：一个女孩搬家时，把一个旧的外国洋娃娃「玛丽」扔掉了。当天夜里电话响起，一个小女孩的声音说：「我是玛丽，我现在在垃圾站。」挂断后电话又响：「我现在在烟草店的拐角。」「我现在在你家门口。」——一通比一通近。最后一通是：「我是玛丽。我现在，在你身后。」故事往往就停在这一句。据说它至少在昭和后期就已经在孩子们之间口耳相传，最早出自哪里，已经说不清了。  各地讲法的差别，多在结尾：有的说女孩回头之后就再也没有出现；有的干脆戛然而止，把想象留给听的人；也有人想出「背贴着墙站，它就绕不到身后」的对策，于是又生出各种接下去的讲法。还有一种说法强调，玛丽本来就是女孩自己珍爱过的娃娃，是被随手丢掉的旧物回来找主人。「电话一通通报出越来越近的位置」这个结构后来被大量模仿和戏仿，在漫画、动画和网络段子里反复出现，有时反而变成了喜剧。  有"},{"v":1,"id":"kotoribako","n":2,"t":"子取箱","s":"旧仓最里面的桐木箱子里，装着一只精巧的机关箱。女人和孩子，不能靠近它。","o":"日本 2ch 怪谈","r":[0],"a":"コトリバコ","k":"「コトリバコ」（子取箱，也写作「子取り箱」）出自 2005 年 6 月日本匿名论坛 2ch 灵异版的一篇长帖。发帖人说，朋友家整理旧仓库时翻出一个精巧的木制机关箱；他们找来另一位家里经营神社的朋友，那位朋友一看见箱子就脸色煞白、当场呕吐，一边给父亲打电话，一边叫人把家里的女人和孩子带出去，随后抱着箱子，嘴里念叨着「没事，没事」把它带走了。帖子的后半，是这位朋友转述的箱子来历。  按帖子的说法：幕末到明治初年，隐岐发生骚乱（1868 年的「隐岐骚动」是真实的历史事件），一个从隐岐逃来的男人被岛根某个长期受欺压的村子收留，作为报答，教村民做这种诅咒之箱。箱子只伤女人和孩子，用意是让仇家断绝血脉；按制作时付出的「代价」分级，读作イッポウ、ニホウ……チッポウ，也就是「一子」到「七子」，最凶的叫「ハッカイ（八开）」。原帖对制法写得相当具体，本游戏不作复述。据说箱子太凶，连造箱的村子也承受不住，最后交"},{"v":1,"id":"inunaki","n":3,"t":"犬鸣村","s":"旧隧道的水泥块后面，据说有一座「日本宪法不适用」的村子。手机的信号格，一格一格地掉。","o":"日本福冈都市传说","r":[0],"a":"いぬなきとうげ","k":"犬鸣峠（いぬなきとうげ）位于日本福冈县宫若市与久山町之间的山里。山口的旧犬鸣隧道在上世纪七十年代新隧道开通后就很少有车走了，后来入口被人用水泥块封住。大约从九十年代起，关于这一带的怪谈在年轻人和网络上越传越多，「犬鸣村」就是其中最出名的一个：据说旧隧道后面有一个与外界断绝来往、不在任何地图上的村子，村口立着写有「この先、日本国憲法つうじません」（此处之后，日本国宪法不适用）的牌子；村子四周拉着挂满空罐头的绳子，一碰就响；闯进去的人会被拿着斧头或镰刀的村民追赶；附近手机没有信号、车子会熄火；峠上的公用电话亭半夜会响。  这些说法都查无实据，不同的人讲出来的版本也各不相同。真实的背景是：「犬鸣」确实是这一带山谷的旧地名，这里后来修建了犬鸣水库（九十年代建成），据说有一部分旧聚落因此迁走、沉进了水底，「消失的村子」的联想大概就是从这里来的。也有一种说法认为，八十年代末旧隧道附近发生过的一起真实刑"},{"v":1,"id":"ushinokubi","n":4,"t":"牛首","s":"世上最可怕的怪谈。人人都听过它的名字，却没有一个人讲得出它的内容。","o":"日本都市传说「牛の首」","r":[0],"a":"牛の首","k":"「牛の首」（牛首）是日本流传很广的一则「讲不出来的怪谈」。人们只传它的外壳：这是世上最可怕的故事，可怕到听的人受不了、讲的人讲不完，所以谁也不知道它讲的是什么——据说听完的人都没有好下场。最常见的「前情」是：一位老师在远足的大巴上讲起了它，孩子们吓得哭喊，等他回过神来，满车的孩子都昏了过去，从此他再也不提；另一种说法是有人想在百物语的最后一个讲它，刚开头就被拦住。无论哪个版本，正文都是空的。  作家小松左京在 1960 年代写过一篇同名短篇小说，把「人人都说它可怕、却谁也讲不出来」的套子写成了一个绝妙的玩笑，这篇小说让这个说法广为人知；但它到底是小说之前就在作家圈子里口耳相传，还是被小说带火了才流进民间，说法不一。有人把它和「件」（牛身人面、生下来说出预言就死去的怪物）、牛头天王、牛鬼一类的形象联想到一起，也有人说它源自饥荒年间的旧事，这些都查无实据——它真正的「内容」，也许就是那句「谁也"},{"v":1,"id":"yotsuya","n":5,"t":"四谷怪谈","s":"首演前夜的剧场。行灯、门板、提灯——有一件不是道具，是她。","o":"江户怪谈·鹤屋南北（1825）","r":[0],"a":"東海道四谷怪談","k":"《东海道四谷怪谈》是四代目鹤屋南北写的歌舞伎狂言，文政八年（1825）七月在江户中村座首演，当时和《假名手本忠臣藏》分两天交替上演——伊右卫门本是赤穗藩的浪人，这出戏是忠臣藏的「外传」。浪人民谷伊右卫门为了攀附富家，让妻子阿岩喝下毁容的毒药；她对镜梳头、头发大把脱落的「髮梳き」，门板一面钉着阿岩、翻过来是仆人小平的「戸板返し」，蛇山庵室里提灯裂开、浮出她的脸的「提灯抜け」，都是这出戏的名场面；老鼠也是戏里反复出现的意象。戏里鬼魂出场时，后台打的是低沉的大鼓「ドロドロ」。  这几场戏靠的是舞台机关和「早替り」：同一个演员在几秒钟里从阿岩换成小平，从提灯里钻出来。葛饰北斋在《百物语》里画的「お岩さん」，就是一盏长着她的脸的破提灯。此后两百年，四谷怪谈被一再改编成歌舞伎、电影和电视剧，阿岩肿起的半边脸成了日本怨灵最有名的形象之一。  戏里的阿岩是虚构的，但名字有来处：东京新宿区四谷左门町有一座於"},{"v":1,"id":"sarayashiki","n":6,"t":"番町皿屋敷","s":"「一枚……两枚……」井底下有人在数盘子，数到九，就哭。","o":"江户怪谈","r":[0],"a":"番町皿屋敷","k":"「皿屋敷」是日本流传最广的怪谈之一。以江户番町为舞台的叫「番町皿屋敷」，以播磨国姬路为舞台的叫「播州皿屋敷」，此外出云、土佐等地也有类似的故事。番町版最常见的说法是：旗本青山家（主人有的说叫主膳，有的说叫播磨）的侍女阿菊，打碎了——或者被人诬陷打碎了——主家视为传家宝的十枚一组的盘子中的一枚，受到严惩后投井，也有说是被投进井里。此后每夜井中传出「一枚、两枚……」的数盘声，数到九枚便放声痛哭，青山家不久断绝。据说江户中期的《皿屋敷弁疑录》（1758）把这件事系在承应二年（1653），但这类记载本身就多有附会，查无实据。  播州版据说更早，和姬路城有关：家老青山铁山图谋夺城，侍女阿菊探知了阴谋，铁山的同伙町坪弹四郎藏起一枚盘子诬陷她，把她杀死投井。姬路城内至今有一口被称作「阿菊井」的井。据说宽政七年（1795）前后，姬路一带大量出现一种形状像被反绑的女人的虫蛹，人们叫它「阿菊虫」（一般认为是麝"},{"v":1,"id":"yukionna","n":7,"t":"雪女","s":"暴风雪夜的渡口小屋。她吹了一口气，老人冻死了；她放过了你——只要你永远不说出今晚。","o":"日本民间传说·小泉八云《怪谈》（1904）","r":[0],"a":"雪女 · Yuki-onna","k":"「雪女」是日本雪国流传很广的妖怪传说。据说最早的文字记载见于托名室町时代连歌师宗祇的《宗祇诸国物语》，讲他在越后国的大雪里见到过雪女。各地说法差别很大：有的说她在雪夜抱着婴儿，求过路人帮忙抱一下，接过来的人会被越来越沉的孩子压进雪里；岩手远野一带说，小正月或冬天满月的夜里，雪女会领着一群孩子出来玩（见柳田国男《远野物语》）；还有「冰柱媳妇」一类的故事：风雪夜来投宿的美丽女子嫁给了男人，却怎么也不肯洗热水澡，被劝着泡进浴桶以后，只剩下一根细细的冰柱。  今天最广为人知的版本出自小泉八云（Lafcadio Hearn）1904 年出版的《怪谈》。他在序里说，这是武藏国西多摩郡调布村的一位农夫讲给他听的家乡传说：樵夫茂作和十八岁的徒弟巳之吉在暴风雪中躲进渡守的小屋，夜里一个白衣女人进来，朝老人吹了一口气，老人冻死；她放过巳之吉，条件是永远不许说出这一夜。第二年冬天，巳之吉在路上遇见名叫阿雪的姑娘"},{"v":1,"id":"noppera","n":8,"t":"无脸人","s":"纪伊国坂的夜里，河边哭泣的女人转过脸来——什么都没有。","o":"日本怪谈·小泉八云《貉》（1904）","r":[0],"a":"のっぺらぼう","k":"「のっぺらぼう」（无脸妖怪）是日本最有名的妖怪之一：看上去是个普通人，脸上却没有眼睛、鼻子和嘴，光溜溜的像一只鸡蛋。江户时代的怪谈集和妖怪画里就有类似的妖怪。它的故事常常是「两段式」的：受惊的人逃到另一个人那里诉说，对方说「你看见的，是不是这样的脸？」再一次露出无脸——日本民俗学里有人把这种结构叫作「再度の怪」，它也出现在不少别的妖怪故事里。  这一类故事里流传最广的，是小泉八云（Lafcadio Hearn）1904 年《怪谈》（Kwaidan）中的《貉》（Mujina）。故事发生在东京赤坂的纪伊国坂：坂的一边是又深又宽的古濠，另一边是高高的宫墙；在有路灯和人力车之前，天黑以后几乎没人敢独自走这条坂。京桥的一位老商人深夜赶路，看见河边一个年轻女子掩面哭泣，上前安慰，她转过脸来，用手一抹——什么都没有。他逃到坂上一个荞麦面摊，老板问：「是不是这样的？」又抹了一把脸，灯随即灭了。八云说，最后"},{"v":1,"id":"resortbaito","n":9,"t":"旅馆打工","s":"海边老旅馆的暑期打工。二楼最里面的房间不许进，老板娘每晚端一碗插着筷子的饭上去。","o":"日本网络怪谈","r":[0],"a":"リゾートバイト","k":"「リゾートバイト」（度假村打工）是日本网络论坛2ch的オカルト板上流传很广的长篇怪谈，一般认为最早贴出于2009年前后，作者匿名，真实身份不可考。故事的大致框架是：几个大学生暑假到海边的旅馆住店打工，旅馆里有一间不许进的房间，老板娘每天晚上把饭菜端上去；年轻人出于好奇偷偷去看，结果其中一人渐渐变得不对劲，最后不得不求助于寺里的和尚，在一连串严格的禁忌里熬过驱邪——出寺下山的时候，绝对不能回头。原帖篇幅很长，后来的转述、漫画和朗读视频在细节上出入不小，这里只取各版本共有的骨架。  故事里的许多细节，借用了日本真实的民间习俗：竖着插在饭上的筷子是供给死者的「枕饭」，所以日常吃饭忌讳把筷子插在饭里；盂兰盆（多数地方在八月十三日至十六日）有烧迎火、送火迎送祖先的习俗；各地都流传「盂兰盆期间不要下海」的说法——据说那几天回来的亡魂会把人拉下水，也有人认为，这其实是因为八月中旬浪大、水母多的经验之谈。"},{"v":1,"id":"sugisawa","n":10,"t":"杉泽村","s":"据说村口的鸟居底下，有一块骷髅形状的石头。找到那个村子的人，回不来。","o":"日本青森都市传说","r":[0],"a":"すぎさわむら","k":"「杉沢村」（すぎさわむら）是日本青森县流传最广的都市传说之一。据说昭和年间，青森的山里有一个村子，某天夜里，一个村民突然发了狂，杀害了全村的人；此后村子再也没有人住，被并入邻近的町村，从地图和行政记录上消失了。传说里，村子的入口有一座破旧的鸟居，鸟居底下有一块形状像骷髅的石头，旁边立着一块牌子：「ここから先へ立ち入る者、命の保証はない」（此处之后，擅入者性命不保）。穿过鸟居，能看见几间废屋，墙上还留着发黑的痕迹。最常见的结尾是：找到村子的人，再也没有回来。  流传的版本很多：有的说几个年轻人开车去探险，在废屋里看见血迹后逃回车上，天亮才发现车身上印满了手印；有的说那块牌子只在特定的时候才看得见；也有的说，村子只是从地图上被抹掉了，「村里人」一直还在。这个传说在1990年代靠口耳相传和早期的网络扩散开来；2000年前后，一档电视节目做了「寻找杉泽村」的特辑，引发了一阵探访热潮，也给当地居民和"},{"v":1,"id":"xiaoqian","n":11,"t":"聂小倩","s":"荒寺里的女子夜夜来找你。她送你金子，却求你带走她的骨头。","o":"清·蒲松龄《聊斋志异》","r":[1],"a":"","k":"《聂小倩》出自清代蒲松龄（1640–1715）的《聊斋志异》。浙江书生宁采臣性情慷爽、自律甚严，常说「生平无二色」。他赴金华，借住城北兰若寺，寺里殿塔壮丽而蓬蒿没人，只住着一个自称秦人的燕赤霞。夜里宁从北墙石窗望见短墙外的小院中，一个衣绯、插蓬沓、驼背的老妇和一个四十来岁的妇人在月下说话，接着来了一个十七八岁的女子。那女子夜入他房中求欢，被他正色拒绝；她又把一锭黄金放在褥上，宁把金子掷到庭中，说「非义之物，污我囊橐」。女子拾金而去，叹道「此汉当是铁石」。「兰若」是梵语「阿兰若」的省称，意为寂静处，后来泛指寺院。  第二天，来赴试的兰溪生和他的仆人先后暴死，足心都有锥刺般的小孔，细细出血。女子再来时说出实情：她叫聂小倩，十八岁夭亡，葬在寺旁，被妖物胁迫害人——狎昵她的人，她暗中以锥刺其足心，摄血供妖物饮用；或者以金相诱，那「金子」其实是罗刹鬼骨，留下的人会被截去心肝。她说妖物将遣夜叉来，劝宁"},{"v":1,"id":"shuigui","n":12,"t":"水鬼找替身","s":"村口那湾水，每年夏天都要带走一个人。河边有人喊你，不要应。","o":"中国民间传说","r":[1],"a":"","k":"「水鬼找替身」是流传很广的中国民间说法：溺水而死的人，魂魄被困在水里，不能离开、不能投胎，要等另一个人在同一处淹死、「顶替」它的位置，才能解脱，所以它会想方设法引人下水。这类故事在明清笔记小说里很常见，各地细节不一：有的说水鬼会变成漂在水面上的财物、衣裳、皮球引人去捞；有的说它会学熟人的声音喊人的名字，所以「夜里在水边听见有人叫你，不要应」；有的地方说穿红衣服容易被水里的东西「看上」，也有说法认为穿红衣溺亡的人怨气重、不肯走。这些都属于民间信仰和口头传说，并无实据。  最有名的「心善的水鬼」出自清代蒲松龄《聊斋志异·王六郎》：渔夫许某每晚饮酒前先酹酒于河，与水鬼王六郎结为朋友；六郎本该由一个抱着孩子落水的妇人替代，却因可怜她怀里的婴儿而放弃，后来被上天任命为招远县邬镇的土地神。「善念能让水鬼脱离找替身」的情节，后来在许多民间故事里反复出现。  端午节在农历五月初五。流传最广的说法是：战国时"},{"v":1,"id":"minghun","n":13,"t":"冥婚","s":"路边有个红包。风把它送到你脚下，你就是新郎了。","o":"中国民间习俗与传说","r":[1],"a":"","k":"冥婚，又叫阴婚、配骨、结阴亲，是给未婚而亡的人办的婚事。它在中国由来已久：《周礼·地官·媒氏》里就有「禁迁葬者与嫁殇者」，说明至迟在那时已有这种风俗，而且官方并不赞成；《三国志》记载曹操的爱子曹冲早夭，曹操为他聘了甄氏的亡女合葬；宋代笔记里还写到专门替亡者说亲的「鬼媒人」。背后的想法大同小异：怕亡者在那边孤单，也怕没有归宿的魂灵不得安宁。  「路边红包」的做法，在台湾和闽南一带的说法里最常见。传统上，未出嫁就过世的女儿不能进自家的祖先牌位，家人有时会把装着她生辰八字、头发或指甲和一些钱的红包放在路边，躲在一旁看——据说捡起红包的男子就是「天定」的新郎，家属会出来认亲，拒绝被认为不吉利。俗称「娶神主牌」，新郎日后仍可另娶，但亡妻被视为正室。各地还有「姑娘庙」，供奉没有出嫁的女性亡灵。民间也流传「捡了红包推不掉」「退亲要让女方自己点头」之类的说法，都属传闻，并无定式。  今天的冥婚大多只是象征"},{"v":1,"id":"fengmen","n":14,"t":"封门村","s":"一个空了几十年的村子。天黑以后，巷子会自己绕回老槐树底下——还有人在唱戏。","o":"中国河南网络都市传说","r":[1],"a":"","k":"「封门村」是流传最广的中国网络「鬼村」之一。最常见的说法是，它在河南沁阳一带的太行山深处（网上也有把它放在别处的版本）。去过的人多次指出，这个村子在老地图上和当地人嘴里一直叫「风门」——两山夹着一个山口，风大；「封门」是网上以讹传讹的写法，至于「封门绝户」之类的得名故事，查不到任何出处。  2000 年代后期起，户外论坛和贴吧里陆续出现「独闯封门村」一类的探险帖，传说越滚越大：坐过就会出事的太师椅、贴着大红囍字的「喜字房」、照片里多出来的人脸、进村 GPS 就失灵、走着走着又回到原地、半夜听见唱戏……它常被列进各种「中国十大灵异地点」，吸引了不少驴友专门去夜宿探险。  当地人和走访过的媒体给出的说法要平常得多：村民是因为山里交通不便、缺水、孩子上学远等现实困难，几十年间陆续搬到了山下，老房子留着，没人住了；「怪脸」多是光影加心理暗示，也有后期加工的；「太师椅」的说法找不到源头，专门带仪器去"},{"v":1,"id":"lintoujie","n":15,"t":"林投姐","s":"三更天，林投林边有个女人来买肉粽。她给的钱，天一亮就变成银纸。","o":"台湾民间传说（清代台南）","r":[1],"a":"","k":"「林投姐」是台湾流传最广的鬼故事之一，和「周成过台湾」「吕祖庙烧金」一起，在二十世纪中叶的通俗读物里被并称为「清代台湾三大奇案」。故事大多放在清朝光绪年间的台南府城：寡妇李昭娘（也有写作「李招娘」的），丈夫早逝，留下一点家产和几个孩子；从唐山来的商人周亚思（也有写作「周阿司」的）取得了她的信任，以合伙做樟脑生意为名，把她的积蓄连同她借来的钱一起带过海，从此音讯全无。债主上门，她走投无路，据说在一棵林投树下结束了生命；孩子们的结局，各个版本说法不一，都很悲惨。  此后，传说夜里有个披头散发的女人到林投林边，向卖肉粽的小贩买粽，给的钱到天亮就变成了银纸（烧给亡者的纸钱）。在常见的版本里，一位算命先生（有的版本叫周天道）听说了她的冤屈，替她刻了神主牌，用一把雨伞遮着，带她上船渡海到汕头（也有说是泉州或「唐山」某地）；周亚思见到她以后发了疯，伤害了自己后来娶的妻儿，最后自己也死了——这是一个典型的"},{"v":1,"id":"minxiong","n":16,"t":"民雄鬼屋","s":"阿嬷留下的老照片，和今晚的拍立得。同一个角度，多出来一个人。","o":"台湾嘉义民间传说","r":[1],"a":"","k":"「民雄鬼屋」位于台湾嘉义县民雄乡，本名「刘家古厝」或「刘家洋楼」。一般的说法是：这栋两层红砖洋楼建于 1929 年前后，屋主是当地的刘姓仕绅，红砖、拱窗、山墙，在当时是很气派的房子。后来刘家迁居他处，房子荒废下来，被榕树的气根一层一层包住，渐渐成了台湾最有名的「鬼屋」之一，常被人列进所谓的「台湾几大鬼屋」。  关于它为什么荒废，流传着好几个版本。最常听到的是「丫鬟投井」：刘家有个丫鬟跳进了宅院里的井，原因各说各话——有人说她和主人有私情被发现，有人说她受了委屈，有人说她被冤枉。另一种说法和军队有关：日本时代末期（也有人说是战后）曾有军队驻扎在这里，夜里有士兵看见井边的女人、听见哭声，后来还出了事。也有人说，后来想拆掉这栋房子，怪手一开进来就故障、工人接连生病，只好作罢。这些说法都查不到可靠的记载，多半是口耳相传、越传越凶。  1990 年代以后，电视灵异节目多次到这里出外景，大学生、夜游的"},{"v":1,"id":"longzhu","n":17,"t":"延安高架龙柱","s":"上海延安路口那根盘龙的柱子，据说当年桩怎么也打不下去。","o":"上海都市传说","r":[1],"a":"","k":"【真实背景】延安高架路与南北高架路在上海市中心的延安路—成都北路交会处相交，形成一座多层的大型立交。立交正当中有一根特别粗的立柱，外面包着一层金属浮雕，盘龙环绕，人称「龙柱」，是上海高架路上唯一一根加了装饰的柱子。南北高架于1993年下半年开工、1995年底通车；按公开报道，这根柱子直径约5米、高约32米，要托起几层桥面，底下的桩长达六十多米。  【流传的说法】关于它，上海流传着一个家喻户晓的说法：当年这里的桩怎么也打不下去，打下去又弹上来。后来请来一位高僧，高僧说此处是「龙脉」所在，地下有龙（也有说是龙穴、龙头），要动工须先安抚。法事之后桩果然顺利打下，柱子外面便包上了九条龙，算是给龙的交代。更进一步的版本还说，高僧泄露了天机，不久便圆寂了。这个故事九十年代就已口耳相传，2000年代以后又在网络论坛上被反复转帖，细节越传越多。  【有出处的说法】参与建设的人后来在报道中给出了另一种解释："},{"v":1,"id":"zhongyuan","n":18,"t":"中元·放河灯","s":"七月半，鬼门开。阿嬷单子上的规矩，一条也莫犯——河灯放下去，莫回头。","o":"中国中元节习俗","r":[1],"a":"","k":"中元节在农历七月十五，名字来自道教的「三元」：正月十五上元天官赐福，七月十五中元地官赦罪，十月十五下元水官解厄。佛教在同一天过盂兰盆节，出自《佛说盂兰盆经》：目连的母亲死后堕入饿鬼道，饭到嘴边就化成火炭，佛陀教目连在七月十五供养十方僧众，才救出母亲。「目连救母」后来成了中元前后最常演的戏。民间则叫它「七月半」「鬼节」，是祭祖的大日子。闽台一带把整个七月叫「鬼月」，一般说七月初一开鬼门、月底关鬼门，十五前后最热闹；各地的说法和日子并不一致。  闽南和台湾的中元普渡，是给没人祭祀的孤魂（客气地称「好兄弟」）办的一场宴席：家家户户把供品摆上庙口的普渡坛，每样插香；纸扎的「大士爷」（面燃大士，一般说是观音的化身）坐镇监督，普渡结束时焚化。竖「灯篙」是为了召请四方孤魂，「放水灯」是为了照引水里的亡魂上岸受供，基隆中元祭的放水灯就很有名。「抢孤」则是普渡结束后，众人攀上高高的孤棚抢夺供品，据说抢到的东"},{"v":1,"id":"guishi","n":19,"t":"鬼市","s":"子时开市，鸡叫就散。卖东西的不说话，买东西的不问价——弟弟的长命锁，摆在了寿摊上。","o":"中国民间传说","r":[1],"a":"","k":"「鬼市」这个词，很早就出现在中国的笔记里。唐人郑熊的《番禺杂记》（原书已散佚，这段话靠后世书籍的转引才留下来）写岭南海边「时有鬼市，半夜而合，鸡鸣而散，人从之，多得异物」。宋代孟元老《东京梦华录》记北宋汴京潘楼东街一带的茶坊「每五更点灯，博易买卖衣服图画花环领抹之类，至晓即散，谓之鬼市子」。这里的「鬼」，多半说的是它半夜聚、天亮散，灯影幢幢、来去无踪，未必真指鬼魂。  在民间故事里，鬼市渐渐成了阴阳交界的集市：子时开，鸡叫散；摊主不吆喝，顾客不问价；买东西要用纸钱，天亮后收到的钱变成纸灰、树叶。流传较广的禁忌有：不说话、不问来历、不吃鬼市的东西、鸡叫前必须离开，否则就回不来了。至于摊上卖「寿数」，用长命锁或八字押着一个人的寿，则是这类故事里常见的变体之一，各地说法不一。  明清以来，北京、天津等地也有被叫作「鬼市」「晓市」的天不亮就开张的旧货集：借着灯笼、马灯照亮，买卖旧衣、古玩、杂物，东"},{"v":1,"id":"jangsanbeom","n":20,"t":"长山虎","s":"门外是妹妹的声音。可妹妹，就睡在房间里。","o":"韩国网络都市传说","r":[2],"a":"장산범","k":"「장산범」（长山虎，也译作长山范）是 2010 年代初开始在韩国网络社区流传的都市传说。长山是釜山海云台区的一座山，海拔六百多米，山脚下就是住宅区。据说山里有一种通体白色长毛的东西，四肢着地，跑得比人快；它不直接伤人，而是模仿人的声音——尤其是家人的声音——把人引进山里。另一种常见的说法是，它的叫声像瀑布或沙沙的风声。  帖子里最常被转述的一幕是：深夜有人在门外用家里某个人的声音叫门，而那个人，此刻就在屋里。名字里的「범」是韩语里对老虎的旧称，有人因此把它和更古老的民间故事联系起来——比如《日月兄妹》（해와 달이 된 오누이）里，老虎吃掉了母亲，扮成母亲去敲兄妹俩的门；孩子们让它把手伸进门缝，摸到的却是一只粗糙的、长着毛的手。2017 年，这个传说还被改编成了电影。  查无实据：没有任何可靠的记录证明长山有这样的动物。网上的「目击」大多来自匿名帖子，细节在一次次转述里越来越多；也有人认为，"},{"v":1,"id":"hkhalmae","n":21,"t":"香港奶奶","s":"1989 年的首尔，放学路上有个半人半猫的老奶奶，会拦住孩子问路：「香港怎么走？」","o":"韩国 1980 年代末校园怪谈","r":[2],"a":"홍콩할매귀신","k":"「香港奶奶鬼」（홍콩할매귀신）是 1980 年代末韩国小学生之间流传最广的校园怪谈之一。最常见的说法是：一位老奶奶抱着心爱的猫坐飞机去香港，飞机失事，她和猫的魂魄合在了一起，变成一半是人、一半是猫的鬼，回到韩国，在放学路上专找小孩；也有版本说，是猫把自己的半条命分给了她。据说她一百米只要十秒左右，还能一下跳出好几米，所以「跑是跑不掉的」。  孩子们同时传着一整套「保命规矩」：天黑以后别在外面；跟她说话，每句话的末尾都要加上「香港」；别让她看见指甲（伸手时要手心朝上）；电话响不满四声不要接；窗外有老奶奶叫你，不要应、不要开窗；躲进厕所第四间也没用。规矩因学校、因地区而不同，常常互相矛盾——这正是口耳相传的怪谈的样子。  据报道，1989 年 6 月，MBC 电视台的新闻节目报道过首尔一些国民学校里的「香港奶奶」恐慌：有的教室里孩子们一听说她「在隔壁班吃小孩」，便哭喊成一片，不少孩子天一黑就不"},{"v":1,"id":"janghwa","n":22,"t":"蔷花红莲","s":"铁山府三年死了五任府使。夜里，东轩外有水声，滴答，滴答——有人浑身湿透，来告状。","o":"韩国古典小说《蔷花红莲传》","r":[2],"a":"장화홍련전","k":"《蔷花红莲传》（장화홍련전）是朝鲜王朝后期流传的古典小说，作者不详，有汉文本和多种谚文本，情节大同小异。一般认为它取材于十七世纪中叶平安道铁山的一桩案子：据说孝宗年间，一位新到任的铁山府使审理了一桩姐妹冤死的案子，后人据此敷衍成书。小说里，铁山座首裴武龙的前妻张氏留下两个女儿蔷花、红莲；续娶的许氏把一只剥了皮的大老鼠塞进蔷花的被褥，诬她小产失节，又让儿子长锁趁夜把她带到池塘边推下水，长锁当场被林中窜出的老虎咬掉了耳朵（一说还有一条胳膊和一条腿）。红莲后来跟着一只青鸟来到池边，也没入了水中。  此后，姐妹的冤魂夜夜向新任府使诉冤，接连几任府使都被吓死，铁山府一度无人敢去。直到一位胆大的府使端坐灯下，问明了冤情，第二天升堂审案：许氏拿出所谓的「胎」作证，府使命人当堂剖开，里面全是老鼠屎，真相大白。许氏和长锁被依律处死（各本刑罚的说法不一），裴武龙获释。姐妹的尸身从池中打捞上来，面色如生，被安葬"},{"v":1,"id":"krasue","n":23,"t":"飞头","s":"夜里，一颗女人的头拖着发光的长影飞出来，找血。她的身子，就藏在村里。","o":"泰国 / 东南亚民间传说","r":[3],"a":"Krasue","k":"「กระสือ」（Krasue，常译作飞头鬼）是泰国最有名的鬼怪之一，柬埔寨（叫 Ap）、老挝、马来半岛也有很相近的说法。流传最广的样子是：一颗女人的头，在夜里离开身子飞出去，脖子底下拖着心肺肠子（本作只画成一道发光的长影）；乡下人说，夜里在田野上飘忽不定的鬼火，就是她。白天，她和普通女人一样，只是常被说成脸色苍白、怕晒、贪睡。  民间的说法里，她夜里找血和生肉吃，最爱刚生过孩子的人家——旧时泰国妇女产后要在屋里「躺火」（อยู่ไฟ，靠炭火烘烤休养一段日子），家里人会在高脚屋底下铺满带刺的枝条，据说她拖着的内脏一钻就会被刺挂住；晾在外面过夜的衣服，第二天会留下血印，是她飞过时拿来擦了嘴，所以老人叮嘱天黑前收衣服。她的身子留在暗处，若被人藏起、挪走或围住，头在天亮前回不去，她就会死。至于这份诅咒从哪来，说法很多：有的说是老飞头临死时，谁接了她嘴里的唾沫或吃食，谁就继承了她；有一种来历故事说"},{"v":1,"id":"manananggal","n":24,"t":"分身女","s":"她的下半身还站在竹林里。天亮之前，别让她合上。","o":"菲律宾民间传说（阿斯旺）","r":[3],"a":"Manananggal","k":"Manananggal（马纳南加尔）的名字来自他加禄语 tanggal——「分开、卸下」。她是菲律宾「阿斯旺」（aswang）一类精怪里最出名的一种：白天是村里普普通通、甚至格外和气的女人；夜里在身上抹油，从腰部断开，上半身长出蝙蝠一样的翅膀飞走，下半身留在原地。人们相信她专找怀孕的女人，趴在椰叶或茅草屋顶上，从缝隙里垂下一条又细又长的舌头。流传最广的破解法是：找到她留下的下半身，在断口上撒盐、抹捣碎的大蒜或撒灰，她就合不回去，天一亮便会死去。大蒜、盐、圣水、黄貂鱼尾做的鞭子（buntot pagi）、刀，都被说成能挡住她；还有一种说法：看阿斯旺的眼睛，映出来的人影是倒着的。  各地说法差别很大。米沙鄢一带常把这类精怪统称为阿斯旺，也有人用夜里的叫声给它们起名：tik-tik、wakwak；据说 tik-tik 声越轻，它其实越近。班乃岛的卡皮斯省在全国「以阿斯旺多出名」，这个名声让不少卡"},{"v":1,"id":"pocong","n":25,"t":"布包鬼","s":"裹尸布上的结，要在下葬时一道一道解开。忘了解的那一个，会自己蹦回来。","o":"印度尼西亚传说「Pocong」","r":[3],"a":"Pocong","k":""},{"v":1,"id":"toyol","n":26,"t":"鬼仔","s":"门锁着，窗关着，钱罐里的钱一夜少一半。豆子、镜子、弹珠、螃蟹——它毕竟是个孩子。","o":"马来西亚民间传说","r":[3],"a":"Toyol","k":""},{"v":1,"id":"naleba","n":27,"t":"明天再来","s":"在门上写「明天再来」。她读了，就走。","o":"印度班加罗尔都市传说","r":[4],"a":"Nale Ba","k":""},{"v":1,"id":"bhangarh","n":28,"t":"巴恩加尔古堡","s":"蓝色告示牌上写着：日出之前、日落之后，不得入内。宫殿的影子，正一点一点爬过集市。","o":"印度拉贾斯坦邦 · 古堡传说","r":[4],"a":"Bhangarh","k":"巴恩加尔（Bhangarh）在印度拉贾斯坦邦阿尔瓦尔县，萨里斯卡自然保护区的边上，离斋浦尔大约两个多小时车程。一般认为它建于十六世纪末，是安伯王室为一位王子修的城：城门、集市、神庙、宫殿依着阿拉瓦利山坡一层层排开。十七世纪以后它渐渐衰落，有一种说法是十八世纪的一场饥荒后人们彻底迁走了。如今城里的房子大多没有屋顶，由印度考古局（ASI）作为受保护古迹管理，戈皮纳特神庙、索梅什瓦尔神庙、集市两旁的石头铺面、「舞女的宅子」和山坡上的宫殿都还看得出模样。  关于它为什么荒废，流传最广的是两个传说。一个说，苦行僧巴鲁·纳特（Guru Balu Nath）同意人们在他修行的地方建城，条件是城里房子的影子不能落到他身上；后来的君主把宫殿越加越高，影子终于落到了他的修行处，城便毁了。据说他的墓（萨玛迪）至今还在城里，附近村民也常说「这里盖的屋顶留不住」。另一个说，懂法术的辛吉亚（Singhia）爱慕公主拉"},{"v":1,"id":"tokoloshe","n":29,"t":"托克洛希","s":"南非山村，家家户户把床脚垫上砖。河里有个矮小的东西，喝了水就谁也看不见——只有孩子看得见。","o":"南非民间传说","r":[4],"a":"Tokoloshe","k":"托克洛希（Tokoloshe，祖鲁语 utokoloshe，科萨语 utikoloshe）是南部非洲祖鲁、科萨等民族民间信仰里的一种精怪。流传最广的说法是：它个子很矮，大约只到人的膝盖，浑身是毛；和水有关，常被说成住在河里；它喝了水、或者吞下一颗小石子，就能隐身，只有孩子看得见它。人们相信它会在夜里来到熟睡的人身边作祟，让人生病、做噩梦，甚至更糟。  防托克洛希最出名的办法，就是把床垫高——在每条床腿下面垫上砖头，据说它太矮，就够不着床上的人。这个习惯在南部非洲流传很广，城里也有人这样做，有的人只是出于习惯，或者「以防万一」。在很多说法里，托克洛希不会自己出现，而是被心怀恶意的人（祖鲁语 umthakathi，施害的巫者）召来、差去害人；传统治疗师（sangoma、inyanga）则被认为能认出并驱走它。治疗师在当地社会里是受人尊敬的角色，和「施害的巫者」是两回事。各地的版本差别很大：有的"},{"v":1,"id":"jazirat","n":30,"t":"红岛空城","s":"沙暴夜里的空村子。墙上的记号，有些不是你画的。","o":"阿联酋 · 拉斯海马","r":[4],"a":"Al Jazirat Al Hamra","k":"红岛（Al Jazirat Al Hamra，阿拉伯语意为「红色的岛」）在阿联酋拉斯海马酋长国的海边，原本是一座以采珠和捕鱼为生的村镇，据研究可能建于十七世纪前后。二十世纪初英国人洛里默（J. G. Lorimer）编的海湾地名辞典里记载，这里约有五百户人家，以扎卜（Za'ab）部落为主。房屋用海里采来的珊瑚石和海滩上的岩石层层垒成，梁是红树木，屋顶铺棕榈叶席；村里有堡垒、瞭望塔、清真寺、集市，以及带风塔（barjeel）的大宅。二十世纪三十年代以后，日本养殖珍珠兴起，加上世界经济萧条，海湾的天然采珠业迅速衰落；石油时代来临后，居民在 1968 年到 1971 年间陆续迁往新的城镇，旧村就此空置，几十年里基本保持原样。如今它是受保护的文化遗址，已被列入联合国教科文组织的《世界遗产预备名单》，近年开始修缮，也会举办一些文化活动。  因为整村一下子搬空，红岛很早就有了「鬼城」的名声。网上流传的"},{"v":2,"id":"deardavid","n":1,"t":"亲爱的大卫","s":"纽约的老公寓。午夜，绿摇椅上坐着一个头瘪了一块的小男孩。你只能问他两个问题。","o":"美国 · 2017年推特连载","r":[5],"a":"Dear David","k":"「亲爱的大卫」（Dear David）出自2017年8月7日起的一串推文：一位住在纽约的插画作者说，他的公寓里闹鬼，是一个死去的小孩，而且那个小孩似乎想杀他。据他讲，他先梦见卧室里的绿色摇椅上坐着一个头部畸形的男孩，男孩从椅子上下来，拖着脚朝床走过来，而他躺着动弹不得；几晚后，另一个梦里的小女孩告诉他：你遇上的是「亲爱的大卫」。规矩是——大卫已经死了，只在午夜出现；见到他可以问两个问题，每问之前必须先叫「亲爱的大卫」；绝不能问第三个，否则他会杀了你。楼主说，他后来在梦里问了三个问题，事情从此变本加厉。第一条推文被转发了几万次。  此后几个月他陆续更新（以下均为楼主自述）：家里的两只猫每到午夜前后就聚到大门口；他隔着猫眼拍下走廊，觉得照片里有东西；拍立得拍的走廊显影出来一片漆黑，网友说在里面看到了人脸；宠物摄像头拍到绿摇椅自己摇动、墙上的龟壳掉落、茶几上的绿玻璃罐自己滑开；睡眠App每晚三点"},{"v":2,"id":"polybius","n":2,"t":"波利比乌斯","s":"没有厂牌的黑色街机。分数越高，画面里藏的东西越多","o":"美国俄勒冈州　1981 年街机都市传说","r":[5],"a":"Polybius","k":"「波利比乌斯」（Polybius）是街机时代最有名的都市传说之一。故事说：1981 年，美国俄勒冈州波特兰郊外的几家游戏厅里出现了一台没有厂牌的街机。它的画面是抽象的矢量图形，玩起来让人上瘾；玩过的人开始失眠、做噩梦、失忆，有的人从此再也不碰电子游戏。每到夜里，会有穿黑西装的人来打开机器「收集数据」。几周后，机器消失了，像从来没存在过。有人说那是政府的心理实验，画面里夹着「服从」「别睡」之类的潜意识讯息——这些细节在不同的版本里各不相同。  这个传说可以追溯到的最早出处，是 2000 年前后一个街机资料网站上的一条条目：只有名字、年份，以及一个据说是德语、意思近似「感官删除」的厂商名「Sinneslöschen」。从那以后，各种「我小时候玩过」的回忆层出不穷，但从来没有人拿出过机柜、电路板、照片或任何当年的记录。目前看来，它查无实据。  有人翻出了 1981 年波特兰当地的旧报道，认为传说"},{"v":2,"id":"candlecove","n":3,"t":"烛湾","s":"几个陌生人在论坛上，一起想起了一部小时候的木偶戏。最后有人说：那个时间段，只有雪花。","o":"美国　2009 年网络怪谈","r":[5],"a":"Candle Cove","k":"「烛湾」（Candle Cove）是2009年发表在网上的一篇短篇恐怖小说，作者是一位美国漫画家。全文模仿怀旧论坛上的一串帖子：几个网友回忆1970年代初在俄亥俄州一带看过的一部儿童节目——小女孩珍妮丝、胆小的木偶海盗佩西、海盗船「笑柄号」，还有一个骷髅脸、乱糟糟的棕胡子、玻璃眼珠，戴高礼帽披披风的「剥皮人」（Skin-Taker），网友们隐约觉得那披风是用人皮做的。他们越聊越多，想起「你得进去」那句台词，想起一集所有角色只是不停尖叫的节目。最后，发帖人去疗养院看母亲，母亲说：你那时总说「妈，我要去看烛湾了」，然后把电视调到雪花，对着没有信号的屏幕看半个钟头。  这篇小说很快被转贴到各个恐怖故事网站，成了最有名的网络怪谈（creepypasta）之一。因为写得太像真帖，不少读者以为真有这部节目，四处打听当年的播出记录——当然查不到。这种「好几个人都记得一件没发生过的事」的味道，后来常被拿来"},{"v":2,"id":"tedcaver","n":4,"t":"泰德的洞穴","s":"老洞最深处，一道会吹风的窄缝。他们决定把它凿宽。","o":"美国　2001 年网络连载","r":[5],"a":"Ted the Caver","k":"「泰德的洞穴」（Ted the Caver）是英语网络早期最有名的恐怖故事之一。据说它最早在2001年前后，以一位洞穴爱好者个人主页上的探洞日志形式出现在一个免费建站网站上：写日志的人自称泰德，和朋友「B」在一个老洞的深处发现了一个小洞口，里面不停地往外吹着强风。风这么大，说明后面有很大的空间，于是他们一趟又一趟地带着锤子、凿子和电钻回去，想把它扩宽钻过去。  日志一篇比一篇不对劲。据说 B 带去的狗到了洞口就焦躁不安；缝的那头传来像是尖叫、又像石头刮着石头的声音；钻过去以后，洞壁上出现了像象形文字一样的图画，画着站在某个记号下面的人；泰德开始做噩梦、出现幻觉，后来同去的一个朋友吓得再也不肯说他看见了什么。最后一篇日志说，他们准备带上枪再下去一次——之后主页再也没有更新。流传最广的说法是，最后一页的链接点下去，只会回到同一页。  因为写成了实时更新的个人日志，还配着真实的洞穴照片，它在当年"},{"v":2,"id":"resurrectionmary","n":5,"t":"复活玛丽","s":"芝加哥西南郊的老舞厅里，穿白裙子的金发姑娘陪你跳了一整晚。她要你沿着阿彻大道，送她回家。","o":"美国 · 芝加哥都市传说","r":[5],"a":"Resurrection Mary","k":"「复活玛丽」（Resurrection Mary）是芝加哥一带流传最广的鬼故事，也是「消失的搭车客」最有名的地方版本之一（《百物语·壹》第七夜讲过那个更古老的骨架）。故事发生在芝加哥西南郊的阿彻大道上：一个金发蓝眼、穿白色舞裙和舞鞋的年轻姑娘，在路边的老舞厅里陪年轻人跳了一整晚的舞。她话很少，手冷得出奇。散场后她请人开车送她，说沿着阿彻大道一直走；车开到复活公墓门口，她要求停车——下了车，就消失在铁门那里。有的版本里，车还没停稳，她就不见了。据说从三十年代起就有人这样讲，七十年代是目击说法最多的时候，出租车司机的讲述尤其多。  关于她是谁，流传的说法大致是：三十年代的一个冬夜，她在舞厅里和男朋友吵了一架，赌气一个人沿阿彻大道走回家，被一辆车撞倒，司机逃逸；家人把她穿着那条白裙子和舞鞋下葬在复活公墓。有人把她和一位死于1934年车祸的年轻姑娘联系起来，也有人说是1927年一个和父亲去舞厅、回"},{"v":2,"id":"robert","n":6,"t":"罗伯特娃娃","s":"一个穿水手服的旧娃娃，住在博物馆的玻璃柜里。给他拍照之前，记得先问他。","o":"美国佛罗里达州基韦斯特","r":[5],"a":"Robert the Doll","k":"罗伯特娃娃（Robert the Doll）是美国佛罗里达州基韦斯特最有名的「闹鬼」娃娃：约一米高，穿白色水手服，怀里抱着一只玩具狮子。一般的说法是，它是二十世纪初德国施泰夫（Steiff）公司的产品，约1904年来到基韦斯特伊顿街一户人家，成了一个男孩的玩具。男孩和娃娃同名，家里人便叫他的中间名「吉恩」；据说他闯了祸总说「是罗伯特干的」。男孩后来成了画家，在巴黎学画时结识了一位钢琴家，婚后回到基韦斯特的老宅，一直把娃娃留在身边。  流传最广的故事都发生在那栋房子里：娃娃有自己的塔楼房间；路过的学生和邻居说看见它在窗户之间换位置；家人听见阁楼有小脚步声和笑声；还有人说它的表情会变。有一个版本把娃娃的「诅咒」归到家中一位来自巴哈马的女佣身上，说她懂巫术——这种说法没有任何依据，带着对加勒比移民及其信仰的偏见，一般认为是后人附会。画家1974年去世后，房子几经易手；1994年，娃娃被捐给基韦斯"},{"v":2,"id":"munecas","n":7,"t":"娃娃岛","s":"霍奇米尔科的运河深处，有一座挂满了娃娃的小岛。弟弟从岛上带回来一个。","o":"墨西哥　霍奇米尔科","r":[5],"a":"Isla de las Muñecas","k":"「娃娃岛」（Isla de las Muñecas）在墨西哥城南部的霍奇米尔科（Xochimilco）。这里的运河网和浮田（chinampa）可以追溯到阿兹特克时代：人们在湖里用泥土和树枝堆出一块块狭长的田，四周种上细高的阿韦霍特柳（ahuejote）固土，田与田之间就成了水道。1987年，霍奇米尔科与墨西哥城历史中心一起被列入世界遗产。如今，游客坐着漆成彩色、拱门上写着女人名字的平底游船（trajinera）游览运河；娃娃岛在特修伊洛湖（Laguna de Teshuilo）附近，从码头出发要坐好一阵船。  流传最广的说法是：上世纪中叶，一位老人独自搬到这座小岛上居住。据说他在岛边的水里发现了一个溺水身亡的小女孩，不久之后，又看见一个娃娃从水上漂来。他把娃娃挂在树上，以示对女孩的敬意，好让她的魂灵安息。此后约五十年，他相信女孩的魂灵一直在岛上，便不停地挂娃娃——从垃圾堆和运河里捡，后来也"},{"v":2,"id":"silbon","n":8,"t":"吹哨人","s":"平原上的口哨声：听着近，他还远；听着远，他就坐在你家门口，数骨头。","o":"委内瑞拉 / 哥伦比亚平原传说","r":[5],"a":"El Silbón","k":"「吹哨人」（El Silbón）是流传在委内瑞拉与哥伦比亚交界的大平原（Los Llanos）上的鬼怪传说。人们描述他极高、极瘦，有人说有六米高，戴一顶破草帽，肩上背着一只口袋，里面装着他父亲的骨头。他的口哨沿着「哆、来、咪、发、嗦、啦、西」的音阶一级一级往上爬，再往下落。平原上最出名的说法是：口哨听着近，他其实还远；听着远，他就在你身边。  他的来历有好几种版本。流传最广的一种说，他是个被宠坏的年轻人，逼父亲去打鹿，想吃鹿的内脏；父亲空手而归，他就杀了父亲。他的祖父发现后，把他绑在树上鞭打，往伤口上抹辣椒，又放狗咬他，最后诅咒他永远背着父亲的骨头在平原上游荡。也有版本说他杀父另有缘由（例如为了妻子），细节各地不同。正因为这段惩罚，人们相信他怕狗、怕辣椒、怕鞭子；有一种说法认为柠檬树枝做的鞭子尤其管用，但这只在部分地方流传。  关于他的禁忌和规矩也很多：据说他专找醉汉和浪荡子，有的说他会从"},{"v":2,"id":"mothman","n":9,"t":"天蛾人","s":"TNT 废弃区的红眼睛之后，小镇怪事一件接一件。把预兆排对顺序，赶在五点之前。","o":"美国西弗吉尼亚　1966—1967","r":[5],"a":"Mothman","k":"「天蛾人」（Mothman）的故事发生在美国西弗吉尼亚州俄亥俄河边的小镇点普莱森特。据当时的报道，1966年11月15日深夜，两对年轻夫妇开车经过镇北的「TNT 区」——二战时期一座军械厂的旧址，到处是覆着草皮的水泥弹药库——在一座废弃的发电厂附近看见一个比人还高、长着大翅膀、眼睛发出红光的东西。他们说它跟着车飞，车速开到每小时一百英里也甩不掉。第二天消息上了报纸，这个东西很快有了外号「天蛾人」，一般认为是借了当年正热播的电视剧《蝙蝠侠》。此后一年多里，当地陆续有不少类似的目击报告；有人说家里的电视那几天怪响，有人说家里的狗朝着红光跑掉了。  1967年12月15日傍晚，下班高峰时分，连接点普莱森特与对岸俄亥俄州加利波利斯的「银桥」突然垮塌。这是一座1928年建成的眼杆链吊桥，因为刷着铝粉漆而得名。据报道，那天有46人遇难。事后的调查认定，原因是吊链上一根眼杆里一道很小的裂纹，在几十年的应"},{"v":2,"id":"jerseydevil","n":10,"t":"泽西恶魔","s":"据说利兹妈妈的第十三个孩子，生下来就长出了蹄子和翅膀，尖叫着从烟囱飞进了松林。","o":"美国新泽西松林传说","r":[5],"a":"Jersey Devil","k":"「泽西恶魔」（Jersey Devil），早年叫「利兹恶魔」（Leeds Devil），是美国新泽西州南部松林泥炭地（Pine Barrens）最出名的传说。流传最广的版本说：1735年前后，利兹角一个被人叫作「利兹妈妈」的女人怀上了第十三个孩子，她在绝望里说了一句「让魔鬼把这一个带走吧」。孩子生下来本是正常的，随即变成了长着蹄子、蝙蝠翅膀、马一样的长脑袋、头上有角、身后拖着分叉尾巴的东西，尖叫着从烟囱飞了出去，从此住进了松林。版本差异很多：有的说她是女巫，有的说是被她赶出门的牧师（或流浪人）诅咒了孩子，有的说孩子的父亲就是魔鬼；年份从十七世纪末到1780年代都有人讲；有的版本里它伤了接生婆，有的说它后来回来过，蹲在母亲的窗外。  有出处的说法：研究者大多认为，「利兹恶魔」这个名字最早是一个家族背上的骂名。十八世纪初，利兹家族有一位出版历书的人，因为在历书里讲占星，和当地的贵格会闹翻，被对"},{"v":2,"id":"headless","n":11,"t":"无头骑士","s":"睡谷的夜路上，有人一声不吭地跟着你的马。他的头，搁在马鞍上。","o":"美国 · 华盛顿·欧文《睡谷传奇》","r":[5],"a":"The Headless Horseman","k":"《睡谷传奇》出自华盛顿·欧文1820年出版的《见闻札记》，托名一位已故的荷兰裔老学究迪德里希·尼克博克留下的遗稿。故事设在大约1790年，哈得孙河东岸、塔里敦附近一道叫「睡谷」的山坳：从康涅狄格来的教书先生伊卡博德·克兰瘦高、迷信、爱唱赞美诗，追求富农范·塔赛尔的独生女凯特琳；他的情敌是村里的好汉布罗姆·范·布伦特，外号「骨头布罗姆」。范·塔赛尔家的聚会散了以后，伊卡博德骑着借来的老马「火药」回家，在威利沼泽边遇见一个一声不吭的骑手，坡顶上才看清他没有头，脑袋搁在马鞍前。伊卡博德被一路追到教堂桥，回头时，那人举起脑袋朝他扔来。第二天，人们只找到他的帽子、被踩坏的马鞍，和一个摔碎的南瓜。欧文没有说破：此后每当有人提起南瓜，布罗姆总是心照不宣地笑。游戏里「布罗姆的恶作剧」和「真的有鬼」两种读法，都来自这个留白。  无头骑士不是欧文的发明。爱尔兰传说里有「杜拉汉」，夹着自己的头骑黑马在夜里报丧；"},{"v":2,"id":"dutchman","n":12,"t":"飞翔的荷兰人","s":"好望角的风暴夜，一条满帆顶风的红帆船放下小艇：替我们把信捎回家吧。","o":"航海传说 · 好望角","r":[7],"a":"The Flying Dutchman","k":"「飞翔的荷兰人」（The Flying Dutchman）是帆船时代流传最广的幽灵船传说：好望角一带的风暴夜里，会出现一条满帆顶风的老式荷兰船，永远靠不了岸。水手们相信看见它是凶兆，随后船就会出事。较早的书面记载出自18世纪末——据说1790年代一本英国人写的航海见闻里，就记下了水手们讲的这条船。1821年，爱丁堡一本杂志刊出小说体的《范德德肯的家书》，加进了这个传说里最有名的细节：幽灵船放下小艇，求过往船只替他们捎信回家，而信上的收信人早已死去多年；接信的船会倒霉。  船长的名字和罪名随版本而变。最常见的叫范德德肯（Vanderdecken），德语地区的版本里也有叫法尔肯堡的；有的说他对着风暴发誓「就是到世界末日也要绕过这个角」，有的说他和魔鬼掷骰子赌掉了灵魂，还有的说他亵渎神明、虐待船员。1839年的一部英国小说和1843年瓦格纳的歌剧《漂泊的荷兰人》让它家喻户晓：歌剧里船长每七年才能"},{"v":2,"id":"celeste","n":13,"t":"玛丽·赛勒斯特号","s":"大西洋上漂着一条双桅船：帆张着，舵空转，一个人也没有。——可桌上，并没有热茶。","o":"大西洋 · 1872年","r":[7],"a":"Mary Celeste","k":"1872年11月7日，美国双桅船（前桅横帆、主桅纵帆，当时也叫「半横帆双桅船」）玛丽·赛勒斯特号从纽约出港，载着1701桶工业酒精，开往意大利热那亚。船上一共十个人：船长本杰明·布里格斯、他的妻子萨拉和两岁的女儿索菲娅，大副艾伯特·理查森、二副安德鲁·吉林、厨师兼管事爱德华·黑德，以及四名德国水手（福尔克特与博兹·洛伦岑兄弟、阿里安·马滕斯、戈特利布·古德沙特）。12月4日午后，加拿大双桅船神恩号（Dei Gratia，船长戴维·莫尔豪斯，装着石油开往直布罗陀）在亚速尔群岛以东发现她独自漂行。大副奥利弗·德沃和二副约翰·赖特登船：船上空无一人，唯一的小艇不见了；货舱积水约三尺半，两台水泵中有一台被拆开，一根测深杆扔在旁边；前舱口和后舱口的盖板被掀开放在甲板上；天文钟、六分仪和船舶文件不见了，航海日志和记事石板还在，石板最后一条写在11月25日上午8时，记的是望见圣玛利亚岛。淡水和口粮够吃半"},{"v":2,"id":"banshee","n":14,"t":"报丧女妖","s":"深夜，屋外有个女人在哭。老人们说，只有老姓的人家，才有人替他们先哭。","o":"爱尔兰民间传说","r":[6],"a":"Banshee · bean sídhe","k":"「报丧女妖」在爱尔兰语里叫 bean sí（旧拼作 bean sídhe，音近「班西」），意思是「仙丘的女人」——住在古冢和土丘里的「仙族」（aos sí）中的一个。她不害人，也不索命，只是在某个家族有人将死之前，夜里在屋外哀嚎。人们多半只听见她，很少看见她；见过的人说法不一：有的说是年轻美丽的姑娘，有的说是披灰斗篷、穿绿衣裳的老妇人，长头发，眼睛哭得通红。还有一种形象，是蹲在河边浅滩上洗衣裳的女人，洗的是快要死的那个人的衣服——古爱尔兰的英雄故事里，战争女神莫丽甘就曾化身「浅滩边的洗衣妇」，苏格兰高地也有类似的 bean nighe。  她只为古老的家族哭。民间常说，只有姓氏前带「Ó」或「Mac」的老盖尔家族才有自己的班西，常被举出的有奥尼尔、奥布赖恩、奥康纳、奥格雷迪、卡瓦纳等。也有不少移民家庭说，亲人在故乡去世的那一夜，他们远在美国、澳大利亚，也听见了她。她的哭声常被拿来和爱尔兰丧礼"},{"v":2,"id":"changeling","n":15,"t":"调换儿","s":"摇篮里的孩子不哭不笑，饿得吓人，一张脸皱得像个小老头。奶奶说：他不是伊万。","o":"欧洲民间传说","r":[6],"a":"changeling","k":"「调换儿」（changeling）是流传在欧洲许多地方的民间信仰：爱尔兰、苏格兰、威尔士、斯堪的纳维亚、德国……都有。人们相信，仙灵、精灵或山妖会偷走人类的婴儿，在摇篮里留下一个替身——有时是他们自己生病或年老的同类，有时干脆是一截被施了法的木头，过不了几天就会「死去」。传说里调换儿的样子大同小异：不哭不笑或者哭个不停，饭量大得吓人却不长个子，脸皱得像老人，眼神不像孩子。防范的办法也很相似：在摇篮上挂张开的剪刀或其他铁器，系红线，夜里不熄火，早早给孩子受洗。在威尔士，人们管仙灵叫「Tylwyth Teg」（美丽的一族），也小心翼翼地称他们为「Bendith y Mamau」（母亲们的祝福），据说这样说好话，他们就不会来找麻烦。  传说里最有名的一种「揭穿」法，是在调换儿面前做一件荒唐事：用蛋壳酿酒，或者用蛋壳给割麦的人煮饭。调换儿看呆了，忍不住开口，一开口就露了馅。格林兄弟收录过一则德国故"},{"v":2,"id":"pied","n":16,"t":"哈默林的捕鼠人","s":"一二八四年，圣约翰与保罗日。穿花衣的人吹着笛子走过街道，孩子们一个接一个跟了上去。","o":"德国下萨克森 · 哈默林传说","r":[6],"a":"Hameln","k":"哈默林（Hameln）是德国下萨克森州威悉河畔的一座小城。关于这件事，最早的说法并不是传说，而是一段语焉不详的记载：据说城里的市场教堂（圣尼古拉教堂）曾有一扇约1300年前后的彩色玻璃窗，画着一个穿花衣的吹笛人和一群穿白衣的孩子，这扇窗在17世纪毁掉了，只留下后人的描述；15世纪中叶的一部手抄本写道：1284年，约翰与保罗日，6月26日，一百三十个生在哈默林的孩子，被一个穿着各色衣服的吹笛人引走，在科彭山附近的刑场一带失踪。城里一份14世纪的记录据说还写过：「我们的孩子离开已经一百年了。」  捕鼠的情节要到16世纪才出现在记载里，后来格林兄弟《德国传说集》（1816）和罗伯特·勃朗宁的长诗《哈默林的花衣吹笛人》（1842）让它家喻户晓：鼠患、悬赏、赖账、吹笛人在约翰与保罗日扮成猎人、戴着奇怪的红帽子回来。各个版本里留下来的孩子不太一样——格林版是一个瞎眼的（找不到路）和一个哑巴（说不出话）"},{"v":2,"id":"erlkonig","n":17,"t":"魔王","s":"「爸爸，你没看见魔王吗？」夜里，父亲抱着发烧的孩子骑马穿过赤杨林。孩子看得见的，你看不见。","o":"歌德叙事诗（1782）","r":[6],"a":"Erlkönig","k":"《魔王》（Erlkönig）是歌德1782年写的叙事谣曲，最初是他的歌唱剧《渔家女》开场时，女主角一边干活一边唱的一首歌。全诗八节，只有四个声音：叙述者、父亲、孩子、魔王。孩子三次说看见、听见了魔王，父亲三次给出平常的解释——雾、风吹枯叶、老柳树；最后一节，父亲赶到院子，怀里的孩子已经死了。诗本身是公有领域，本作里的中文为自译。  「魔王」这个词有一段曲折的来历。通常的说法是：赫尔德在1778—1779年出版的《民歌集》里，把丹麦民谣《奥卢夫先生》（精灵王的女儿请骑士跳舞，他不肯，被她夺了性命）译成德文《魔王的女儿》，把丹麦语里的「精灵王」译成了 Erlkönig，字面上成了「赤杨之王」——一般认为这是误译。歌德沿用了这个词，魔王的女儿们、夜里的轮舞，都来自这一支传统。  1815年，十八岁的舒伯特把它谱成艺术歌曲（后来作为他的作品第1号出版）：一个歌手要唱四个角色，钢琴不停的三连音像马蹄"},{"v":2,"id":"babayaga","n":18,"t":"芭芭雅嘎","s":"鸡腿上的小屋，骨头扎的篱笆。继母说：家里没火了，去林子里，跟芭芭雅嘎借一点。","o":"斯拉夫民间传说","r":[6],"a":"Баба-яга","k":"芭芭雅嘎（Баба-яга）是斯拉夫民间故事里最有名的老巫婆。她住在密林深处一座立在鸡腿上的小木屋里，屋子会转身，要念一句「小木屋，小木屋，背朝树林，面朝我」才肯把门转过来；她出门坐一只石臼，用捣杵赶着走，用扫帚扫掉身后的痕迹；院子的篱笆是人骨头扎的，桩子上插着眼睛会发光的头骨。她吃人，可也常常是给主人公出难题、赠宝物的那个人——故事里她到底是恶是善，要看来的人怎么做。她的名字从哪里来，学者们至今说法不一；也常有人说她原本是古代斯拉夫人信奉的某位掌管死亡或冬天的女神——这类说法多是后人的推测，并没有可靠的证据。  本章主要依据俄国民俗学家阿法纳西耶夫在《俄罗斯民间故事集》（1855—1863）里收录的《美丽的瓦西丽莎》：母亲临死前把一个小娃娃留给女儿，嘱咐她「给她吃一点，问问她」；继母让女儿们弄灭了家里的火，打发瓦西丽莎去芭芭雅嘎那儿借火；路上先后有白、红、黑三个骑士奔过，芭芭雅嘎说他们是"},{"v":2,"id":"rusalka","n":19,"t":"水仙女","s":"人鱼周的夜里，白桦树上有个绿头发的姑娘在荡秋千。她会问你：手里拿的是苦艾，还是欧芹？","o":"斯拉夫民间传说","r":[6],"a":"Русалка","k":"「水仙女」在东斯拉夫（俄罗斯、乌克兰、白俄罗斯）的民间叫 rusalka。和西欧长着鱼尾巴的美人鱼不同，乡下故事里的她们多半是有腿的年轻姑娘：披着长长的、湿漉漉的头发（有些地方说是绿色的，像水草），穿白衬衣或者什么也不穿，头戴花环。人们说她们是没出嫁就死去的姑娘，尤其是淹死的；也有人说是没受洗就夭折的孩子。她们平时住在河里、湖里，到了初夏就上岸来，坐在白桦和柳树的枝上荡秋千、梳头，在开花的黑麦田里奔跑；遇见的人，或者被她们挠痒挠到死，或者被歌声和笑声引进水里。  她们出没的时节叫「人鱼周」（русальная неделя），在许多地方就是圣三一主日（复活节后第五十天）前后的那一周，和古老的「绿色节期」叠在一起：屋里插白桦枝、地上撒青草，姑娘们编花环扔进河里占卜婚事。这一周有许多禁忌：不下河洗澡，某些日子不干活——乌克兰一些地方把这周的礼拜四叫作「水仙女的复活节」。人们往树上挂衬衣、绣巾和"},{"v":2,"id":"dyatlov","n":20,"t":"迪亚特洛夫山口","s":"那天夜里，九个人从里面割开帐篷，走进了风雪。六十年后，你们在同一片坡上，扎下同一种帐篷。","o":"苏联乌拉尔山 · 1959 年真实事件","r":[6],"a":"Перевал Дятлова","k":"1959 年 1 月底，一支以乌拉尔工学院学生和毕业生为主的十人滑雪登山队从斯维尔德洛夫斯克（今叶卡捷琳堡）出发，计划穿越北乌拉尔、登上奥托滕山。途中一名队员因病折返，成了唯一的生还者。2 月 1 日，其余九人在奥斯皮亚河上游的林子边搭了存储仓，傍晚在霍拉特-西亚赫尔山（曼西语，常被译作「死山」）的东坡上挖开积雪，扎下帐篷，此后再无音讯。2 月下旬，搜救队在坡上找到了帐篷：帐篷被从里面割开，大部分靴子和外衣留在里面，雪地上的脚印一直通向坡下一公里多外的林子边。九人在之后的几个月里陆续被找到，都已遇难。1959 年 5 月，调查以「不可抗拒的自然力量」结案。后来，那道山口以这支队伍队长的姓氏命名。  因为留下的疑点太多，六十年来众说纷纭：雪崩（反对者说坡度不够陡、也没看到明显的雪崩痕迹）；山脊上的风形成「卡门涡街」、产生让人恐慌的次声（2010 年代流行起来的说法）；军方的武器或火箭试验（据"},{"v":2,"id":"golem","n":21,"t":"布拉格的魔像","s":"星期五的黄昏，拉比忘了取下泥人嘴里的字条。它额上写着「真理」——去掉一个字母，就是「死」。","o":"布拉格犹太社区传说","r":[6],"a":"golem","k":"魔像（golem）一词，在希伯来文里有「未成形之物」的意思，《诗篇》第139篇里就用过它。《塔木德》记载过一位拉比造了一个人，另一位拉比跟它说话，它不回答，于是被说「你是用尘土做的，回到尘土里去」。后来，按照《创造之书》一类的神秘传统用字母和圣名让泥土站起来的故事，在中欧犹太社区里流传了好几百年。据流传的说法，额上写 emet（真理）、抹去 aleph 便成了 met（死）的情节，在十七世纪的记述里就已出现，常和波兰海乌姆的以利亚拉比连在一起。  犹大·勒夫·本·比撒列（约1520—1609），人称「马哈拉尔」，是十六世纪布拉格真实存在的大学者，以《塔木德》注释和哲学著作闻名，他的墓至今在布拉格老犹太墓园，来访的人在墓碑上放石子、塞写着心愿的小纸条。可是在他本人和同时代人的文字里，找不到他造过魔像的记载——把魔像和他连在一起，是十八、十九世纪以后的事。十九世纪中叶布拉格出版的犹太故事集让这"},{"v":2,"id":"marykings","n":22,"t":"玛丽金巷","s":"爱丁堡地底下压着一条十七世纪的小巷。一间小屋里堆满了玩具——都是送给一个叫安妮的小女孩的。","o":"苏格兰 爱丁堡传说","r":[6],"a":"Mary King’s Close","k":"玛丽金巷（Mary King’s Close）是爱丁堡老城皇家一英里大道边上的一条小巷，以十七世纪住在这里的一位商人寡妇玛丽·金得名。1753 年起，市里在巷子上方修建皇家交易所（今天的爱丁堡市政厅），巷子的上半截房子被拆掉，下半截被压在大楼底下当了地基，从此成了「地下的街」。据说一直到十九世纪末还有人住在里面。2003 年，这里作为景点「真实的玛丽金巷」对外开放，导游穿着十七世纪的服装，带游客顺着陡峭的石阶往下走。  1645 年，爱丁堡暴发了最后一场大鼠疫。流传的说法是：染病的人家要在窗外挂白旗示警，全家隔离；据记载，市里还专门聘请过瘟疫医生。鸟嘴面具、嘴里塞香草的形象更多来自欧洲大陆，但常被和这条巷子联系在一起。最出名的传说是「封巷」——市里把染疫的居民连人带房封死在巷子里，任其死去。这个说法流传极广，却查无实据，历史学者多认为它是后来附会出来的。1685 年出版的一本讲鬼神的书里，"},{"v":2,"id":"brownlady","n":23,"t":"布朗夫人","s":"诺福克的老庄园。快门开着的时候谁也别动——楼梯上会多出一个穿棕色锦缎裙子的女人。","o":"英国诺福克 · 1936年","r":[6],"a":"Raynham Hall","k":"雷纳姆庄园（Raynham Hall）在英格兰东部的诺福克郡，三百多年来一直是汤森家族的宅邸。传说中的「布朗夫人」（The Brown Lady），据说就是十八世纪初的女主人多萝西·沃波尔——英国第一位首相的妹妹、第二代汤森子爵的第二任妻子。流传最广的说法是：子爵疑心她不忠，把她关在庄园楼上的房间里，连孩子都不让见，直到1726年她在那里去世。官方记载她死于天花；也有人说她是从楼梯上摔下去的，还有人说那场葬礼是假的、她其实又被关了很多年。这些说法大多查无实据。  关于她的目击，最有名的有两次。据说1835年圣诞节，一位来做客的上校在楼梯上看见一个穿棕色锦缎裙子的女人，脸上发着光，眼睛的位置却是两个黑洞。第二年，一位以写海洋小说出名的海军军官来庄园做客，特意要求住进挂着她画像的那间「闹鬼的房间」；据说他夜里在走廊上撞见她提着一盏灯走过来，对着他笑了一下，他抬手就开了枪——子弹穿过她，打进了她"},{"v":2,"id":"compana","n":24,"t":"圣伴","s":"夜里的老路上，一排烛光跟在你身后。别回头，别停，十字架不能交给任何人。","o":"西班牙加利西亚民间传说","r":[6],"a":"Santa Compaña","k":"圣伴（加利西亚语 A Santa Compaña，也叫 Estadea 等）是西班牙西北部加利西亚最有名的民间传说之一，阿斯图里亚斯、莱昂一带也有相近的说法（如 Güestia）。流传最广的版本是：深夜的乡间小路上，一队亡灵排成行列缓缓走过，他们穿着白衣或戴着兜帽，每人手里一支蜡烛；有时人看不见他们，只闻到蜡烛的气味、听见一只小铃铛，狗会狂吠，风会忽然变冷。据说圣伴经过谁家门口，那家不久就会有人去世。  据说走在行列最前面的是一个活人，举着十字架，有的版本里还提着一桶圣水。他不能回头，也不能放下十字架；白天什么都不记得，只是一天天苍白、消瘦，直到在夜路上碰见另一个人、把十字架交出去，才得解脱，否则就会被耗尽。所以老人告诫：夜里遇见圣伴，要在地上画一个圈（有人说还要画「所罗门的记号」，即五角星）站进去，或者脸朝下趴在地上，或者抱住路边的石十字架；他们递来的东西，一样都不要接。  石十字架（c"},{"v":2,"id":"gevaudan","n":25,"t":"热沃当怪兽","s":"1765 年春，山里的牧场上，一头比狼还大的野兽。它放着羊群不碰，专找放羊的孩子。","o":"法国 1764—1767 年真实事件","r":[6],"a":"la Bête du Gévaudan","k":"「热沃当怪兽」（la Bête du Gévaudan）是法国历史上真实发生过的一连串野兽袭人事件。从1764年夏天到1767年6月，在热沃当（大致是今天的洛泽尔省一带）和相邻的马尔热里德山区，牧场上接连有人遇袭。遇难者大多是独自放牧的妇女和孩子，各家统计不一，常见的说法是八九十人到一百多人，伤者更多。目击者说它比狼大得多，毛色红褐，背上一道黑纹，尾巴又长又粗，胸前发白；它常常对近在眼前的牲畜不理不睬，专找放牧的人。  【有出处的说法】事件惊动了宫廷。1764年秋起，龙骑兵进山驻扎搜捕，据说还让士兵扮成农妇引它出来；1765年1月，七个放牧的孩子用绑了刀的棍子把它赶跑，得到国王的赏赐；同年诺曼底的猎狼人奉命前来，夏天由国王的火枪手接手，9月在沙兹修道院附近打死一头大狼，做成标本送往凡尔赛，宣布事情结束——可到了冬天，袭击又开始了。1767年6月19日，一个本地猎人在莫歇山的一片沼地里打死了"},{"v":2,"id":"nokken","n":26,"t":"水妖奈克","s":"星期四的晚上，溪边有人拉琴。听见的人会跟着跳，一直跳进水里。","o":"瑞典民间传说 · Näcken","r":[6],"a":"Näcken","k":""},{"v":2,"id":"krampus","n":27,"t":"坎卜斯","s":"圣尼古拉之夜，跑铃的队伍里多出了一个。它满身铃铛，一声不响。","o":"阿尔卑斯山区民间传说","r":[6],"a":"Krampus","k":"【流传的说法】坎卜斯（Krampus）是阿尔卑斯山区——奥地利、德国巴伐利亚、意大利南蒂罗尔、斯洛文尼亚等地——圣尼古拉节习俗里的「黑色同伴」。12月6日是圣尼古拉的瞻礼日，前一夜12月5日被称作「坎卜斯之夜」（Krampusnacht）。按老规矩，圣尼古拉挨家走访，给乖孩子苹果、坚果、橘子和糖；跟在他身后的坎卜斯长着山羊角、浑身黑毛、吐着长长的红舌头，身上拖着锁链、挂着大大小小的铃铛，手里拿一把桦枝，背上背着篓子或麻袋——据说最调皮的孩子会被塞进去带走。在许多画像和老贺卡上，它一只脚是分瓣的山羊蹄，一只是人脚。  【有出处的说法】一般认为这个名字来自古高地德语里表示「爪子」的词。锁链常被解释为基督教会「捆住魔鬼」的象征。有民俗学者推测它源于基督教之前的冬日习俗，但历史学家多认为证据不足——相关记载要到16世纪才出现。19世纪起，印着「Gruß vom Krampus!（坎卜斯问候你！）」"},{"v":2,"id":"minmin","n":28,"t":"敏敏光","s":"昆士兰内陆的荒原上，有一团光。你追它，它就退；你跑，它就跟。","o":"澳大利亚昆士兰内陆传说","r":[7],"a":"Min Min light","k":"敏敏光（Min Min light）是流传在澳大利亚内陆的一种怪光，目击多集中在昆士兰西部的「河道之乡」（Channel Country）一带，从新南威尔士的布雷沃里纳到昆士兰的博利亚都有人讲起。流传的描述大同小异：一团边缘模糊的光，多半是白色，有时会由白变红、变绿；它悬在地平线上方，会靠近人，会跟着骑马或开车的人走，有人说它和车并排跑了很远；你朝它走过去，它就往后退；据说有人开枪打它，它一下子灭了，过一会儿又在别处亮起来。民间还有一句吓人的话：追上它的人，再也回不来讲这个故事。  它的名字通常被认为来自博利亚以东一百公里左右的小地方敏敏（Min Min）。那里曾有一家路边酒馆兼驿站，据说二十世纪初毁于一场大火，只剩下石头地基和后面的一小片坟地，如今已是无人居住的「鬼镇」。最常被讲起的一个版本是：大约1918年，一个牧工夜里骑马经过酒馆旧址，看见坟地里升起一团光，越变越大，像个西瓜，朝他飘"},{"v":2,"id":"pharaoh","n":29,"t":"法老的诅咒","s":"「死亡将展开翅膀，降临到打扰法老安息的人身上。」——报纸上是这么写的。墓里写的，是另一句话。","o":"1922—1923 埃及帝王谷","r":[4],"a":"Curse of the Pharaohs","k":"1922年11月4日，在英国贵族卡纳冯勋爵出资、霍华德·卡特主持的发掘中，工人们在帝王谷拉美西斯六世墓下方清理古代工匠小屋的遗迹时，发现了一级凿进岩石的台阶。十六级台阶下，是第十八王朝少年国王图坦卡蒙的墓（编号KV62）：11月26日前室被打开，1923年2月墓室的封墙被拆开，里面是几乎填满整间屋子的镀金神龛。墓中出土了五千多件文物，清理、登记和保护持续了约十年。这座墓是埃及工人们挖开的：据卡特本人的记录，发掘队的大工头是艾哈迈德·杰里加尔，工头还有加德·哈桑、侯赛因·阿布·阿瓦德和侯赛因·艾哈迈德·赛义德，他们带着来自西岸村庄的工人清运碎石、守卫墓室、搬运文物。流传很广的「第一级台阶是送水的男孩侯赛因·阿卜杜·拉苏尔发现的」，来自他的家族和后来的口述，当年的发掘日记里没有写，真假难以考证。  「诅咒」是报纸炒作出来的。1923年1月，勋爵把发掘消息的独家报道权卖给了伦敦《泰晤士报》，其他"},{"v":2,"id":"flannan","n":30,"t":"灯塔","s":"大西洋上的孤岛灯塔。规矩说，三个看守永远不许同时出门。1900 年冬天，他们一起不见了。","o":"苏格兰 · 1900 年真实事件","r":[6],"a":"Flannan Isles","k":"弗兰南群岛（Flannan Isles）在苏格兰外赫布里底群岛刘易斯岛以西约二十英里，七座小岛常年无人居住，水手们叫它们「七猎人」。最大的一座叫大岛（Eilean Mòr），岛上有一间据说供奉圣弗兰南的小礼拜堂遗迹，小得后来的灯塔看守管它叫「狗窝」。十八世纪初，一位记述西部群岛风俗的作者写道：刘易斯人每年夏天上岛捡鸟蛋、取羊毛，爬上岛顶时要脱帽、顺着太阳转一圈致谢；在岛上不能用平常的名字称呼这片岛，只能叫它「那片地方」，不少平常的词也要换一个说法。岛上的灯塔 1895 年动工，1899 年 12 月 7 日第一次点亮，灯质是白光两闪、每 30 秒一组，直到今天。  1900 年 12 月 15 日午夜前后，一艘从美国驶往利斯的汽船经过附近，看见弗兰南的灯没有亮，但直到靠岸才报告。补给船因为天气耽搁，12 月 26 日中午才到岛上：旗杆上没有旗，码头上没有摆出空箱子，也没有人来接船。替班看守"}];
